pub fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Nil, Value::Nil) => true,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Int(x), Value::Int(y)) => x == y,
        (Value::Float(x), Value::Float(y)) => x == y,
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Table(x), Value::Table(y)) => std::rc::Rc::ptr_eq(x, y),
        (Value::Native(x), Value::Native(y)) => std::rc::Rc::ptr_eq(x, y),
        (Value::Function(x), Value::Function(y)) => std::rc::Rc::ptr_eq(x, y),
        (Value::Class(x), Value::Class(y)) => std::rc::Rc::ptr_eq(x, y),
        (Value::Instance(x), Value::Instance(y)) => std::rc::Rc::ptr_eq(x, y),
        (Value::EnumVariant(x), Value::EnumVariant(y)) => std::rc::Rc::ptr_eq(x, y),
        (Value::Enum(x), Value::Enum(y)) => std::rc::Rc::ptr_eq(x, y),
        // Cross-type comparisons are always false (Lua semantics).
        _ => false,
    }
}

//! Statement execution with control-flow propagation.

use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

use saule_ast::{ClassMember, Decl, Expr, Param, Spanned, Stmt};

use crate::env::Environment;
use crate::error::{RuntimeError, unsupported};
use crate::value::{ClassObject, FieldDef, FunctionBody, FunctionObject, Value};

use super::{Flow, expr};

/// Execute a sequence of statements in `env`. Stops at the first non-`Normal`
/// outcome and propagates it.
pub fn exec_block(
    stmts: &[Spanned<Stmt>],
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let mut last = Flow::nil();
    for stmt in stmts {
        match exec(stmt, env)? {
            Flow::Normal(v) => last = Flow::Normal(v),
            other => return Ok(other),
        }
    }
    Ok(last)
}

/// Run a block in a fresh child scope. The scope is dropped on return.
fn exec_scoped_block(
    stmts: &[Spanned<Stmt>],
    parent: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let scope = Environment::with_parent(parent.clone());
    exec_block(stmts, &scope)
}

/// Execute a single statement.
pub fn exec(stmt: &Spanned<Stmt>, env: &Rc<RefCell<Environment>>) -> Result<Flow, RuntimeError> {
    let span = stmt.span.clone();
    match &stmt.value {
        Stmt::Local { name, value, .. } => {
            let v = match value {
                Some(e) => expr::eval(e, env)?,
                None => Value::Nil,
            };
            env.borrow_mut().define(name.clone(), v);
            Ok(Flow::nil())
        }

        Stmt::LocalMulti { names, values } => {
            // Evaluate every RHS first so `local a, b = b, a` works at the
            // outer scope. The final expression may expand into multiple
            // return values (Lua-style destructuring semantics).
            let evaluated = eval_expr_list(values, env)?;
            for (i, (name, _)) in names.iter().enumerate() {
                let v = evaluated.get(i).cloned().unwrap_or(Value::Nil);
                env.borrow_mut().define(name.clone(), v);
            }
            Ok(Flow::nil())
        }

        Stmt::Assign { target, value } => exec_assign(target, value, env),

        Stmt::AssignMulti { targets, values } => {
            // Evaluate all RHS expressions first to support parallel
            // semantics (e.g. `a, b = b, a + b`). The final expression may
            // expand into multiple return values.
            let evaluated = eval_expr_list(values, env)?;
            for (i, target) in targets.iter().enumerate() {
                let v = evaluated.get(i).cloned().unwrap_or(Value::Nil);
                assign_target(target, v, env)?;
            }
            Ok(Flow::nil())
        }

        Stmt::Expr(e) => Ok(Flow::Normal(expr::eval(e, env)?)),

        Stmt::If {
            cond,
            then_block,
            elseifs,
            else_block,
        } => {
            if expr::eval(cond, env)?.is_truthy() {
                return exec_scoped_block(then_block, env);
            }
            for (econd, ebody) in elseifs {
                if expr::eval(econd, env)?.is_truthy() {
                    return exec_scoped_block(ebody, env);
                }
            }
            if let Some(eb) = else_block {
                return exec_scoped_block(eb, env);
            }
            Ok(Flow::nil())
        }

        Stmt::While { cond, body } => {
            while expr::eval(cond, env)?.is_truthy() {
                match exec_scoped_block(body, env)? {
                    Flow::Normal(_) | Flow::Continue => continue,
                    Flow::Break => break,
                    ret @ Flow::Return(_) => return Ok(ret),
                }
            }
            Ok(Flow::nil())
        }

        Stmt::Repeat { body, cond } => {
            // Lua semantics: the `until` condition sees locals declared in
            // the body, so condition and body must share the same scope.
            loop {
                let scope = Environment::with_parent(env.clone());
                match exec_block(body, &scope)? {
                    Flow::Normal(_) | Flow::Continue => {}
                    Flow::Break => break,
                    ret @ Flow::Return(_) => return Ok(ret),
                }
                if expr::eval(cond, &scope)?.is_truthy() {
                    break;
                }
            }
            Ok(Flow::nil())
        }

        Stmt::ForNumeric {
            var,
            var_ty: _,
            from,
            to,
            step,
            body,
        } => exec_for_numeric(var, from, to, step.as_ref(), body, env, span),

        Stmt::ForIn { vars, iter, body } => exec_for_in(vars, iter, body, env, span),

        Stmt::Return(exprs) => {
            let values = if exprs.is_empty() {
                vec![Value::Nil]
            } else {
                eval_expr_list(exprs, env)?
            };
            Ok(Flow::Return(values))
        }

        Stmt::Break => Ok(Flow::Break),
        Stmt::Continue => Ok(Flow::Continue),

        Stmt::Throw(_) => Err(unsupported("throw", span)),
        Stmt::Try { .. } => Err(unsupported("try/catch", span)),
        Stmt::Decl(decl) => exec_decl(decl, env),
    }
}

fn eval_expr_list(
    exprs: &[Spanned<Expr>],
    env: &Rc<RefCell<Environment>>,
) -> Result<Vec<Value>, RuntimeError> {
    let mut out = Vec::new();
    for (i, expr_node) in exprs.iter().enumerate() {
        if i + 1 == exprs.len() {
            out.extend(expr::eval_values(expr_node, env)?);
        } else {
            out.push(expr::eval(expr_node, env)?);
        }
    }
    Ok(out)
}

// ─── Declarations ────────────────────────────────────────────────────────────

fn exec_decl(
    decl: &Spanned<Decl>,
    env: &std::rc::Rc<std::cell::RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let span = decl.span.clone();
    match &decl.value {
        Decl::Function {
            name, params, body, ..
        } => {
            let func = FunctionObject {
                name: Some(name.clone()),
                params: params.clone(),
                body: FunctionBody::Block(body.clone()),
                closure: env.clone(),
            };
            env.borrow_mut()
                .define(name.clone(), Value::Function(std::rc::Rc::new(func)));
            Ok(Flow::nil())
        }
        Decl::Class { .. } => exec_class_decl(decl, env),
        Decl::Interface { .. } => Err(unsupported("interface declaration", span)),
        Decl::Enum { .. } => Err(unsupported("enum declaration", span)),
        Decl::Import { .. } => Err(unsupported("import", span)),
    }
}

/// Materialize a `Decl::Class` into a [`ClassObject`] and install it under
/// the class's name in `env`. Method closures all capture `env` so they can
/// see the class itself (used by static calls) and other top-level names.
fn exec_class_decl(
    decl: &Spanned<Decl>,
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let span = decl.span.clone();
    let Decl::Class {
        name,
        extends,
        members,
        ..
    } = &decl.value
    else {
        unreachable!("exec_class_decl called with non-class decl");
    };

    // Resolve parent class, if any. Must already exist in scope.
    let parent = if let Some(pname) = extends {
        match env.borrow().get(pname) {
            Some(Value::Class(c)) => Some(c),
            Some(other) => {
                return Err(RuntimeError::TypeError {
                    message: format!(
                        "cannot extend `{}`: expected a class but got `{}` — check class definition",
                        pname, other.type_name()
                    ),
                    span,
                });
            }
            None => {
                return Err(RuntimeError::Undefined {
                    name: pname.clone(),
                    span,
                });
            }
        }
    } else {
        None
    };

    let mut field_defs: Vec<FieldDef> = Vec::new();
    let mut methods: HashMap<String, Rc<FunctionObject>> = HashMap::new();
    let mut static_fields: HashMap<String, Value> = HashMap::new();
    let mut static_methods: HashMap<String, Rc<FunctionObject>> = HashMap::new();
    let mut constructor: Option<Rc<FunctionObject>> = None;

    // Scan once so we know whether the class has a constructor (`fn init`).
    // When it doesn't, `local field = expr` declarations are promoted to
    // statics so callers can read them via `ClassName.field` (and through
    // the class-as-`self` convention used inside `static fn`s).
    let has_init_method = members.iter().any(|m| match &m.value {
        ClassMember::Method(meth) => meth.name == "init" && !meth.is_static,
        _ => false,
    });

    for member in members {
        match &member.value {
            ClassMember::Field {
                is_static,
                name: fname,
                default,
                ..
            } => {
                // Promote `local field = expr` to a static when there's no
                // constructor — otherwise we'd never be able to read it.
                let treat_as_static = *is_static || (!has_init_method && default.is_some());
                if treat_as_static {
                    // Static defaults are evaluated once, at class
                    // declaration time, in the enclosing scope.
                    let value = match default {
                        Some(e) => expr::eval(e, env)?,
                        None => Value::Nil,
                    };
                    static_fields.insert(fname.clone(), value);
                } else {
                    field_defs.push(FieldDef {
                        name: fname.clone(),
                        default: default.clone(),
                    });
                }
            }
            ClassMember::Method(m) => {
                let func = Rc::new(make_function(
                    Some(format!("{name}.{}", m.name)),
                    m.params.clone(),
                    m.body.clone(),
                    env,
                ));
                if m.is_static {
                    static_methods.insert(m.name.clone(), func);
                } else if m.name == "init" {
                    // `init` is the only constructor spelling — always promote.
                    constructor = Some(func);
                } else {
                    methods.insert(m.name.clone(), func);
                }
            }
        }
    }

    let class = Rc::new(ClassObject {
        name: name.clone(),
        parent,
        field_defs,
        methods,
        static_fields: RefCell::new(static_fields),
        static_methods,
        constructor,
    });

    env.borrow_mut().define(name.clone(), Value::Class(class));
    Ok(Flow::nil())
}

fn make_function(
    name: Option<String>,
    params: Vec<Param>,
    body: Vec<Spanned<Stmt>>,
    closure: &Rc<RefCell<Environment>>,
) -> FunctionObject {
    let _ = closure; // silence unused if we change capture
    FunctionObject {
        name,
        params,
        body: FunctionBody::Block(body),
        closure: closure.clone(),
    }
}

// ─── Assignment ──────────────────────────────────────────────────────────────

fn exec_assign(
    target: &Spanned<Expr>,
    value: &Spanned<Expr>,
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let v = expr::eval(value, env)?;
    assign_target(target, v, env)
}

fn assign_target(
    target: &Spanned<Expr>,
    v: Value,
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    match &target.value {
        Expr::Ident(name) => {
            if env.borrow_mut().assign(name, v) {
                Ok(Flow::nil())
            } else {
                Err(RuntimeError::AssignUndeclared {
                    name: name.clone(),
                    span: target.span.clone(),
                })
            }
        }
        // `obj.field = v` / `Class.static = v`
        Expr::Member { obj, name } => {
            let receiver = expr::eval(obj, env)?;
            assign_member(&receiver, name, v, target.span.clone())
        }
        Expr::Index { obj, index } => {
            let receiver = expr::eval(obj, env)?;
            let index_value = expr::eval(index, env)?;
            assign_index(&receiver, index_value, v, target.span.clone())
        }
        _ => Err(RuntimeError::InvalidAssignTarget {
            span: target.span.clone(),
        }),
    }
}

fn assign_member(
    receiver: &Value,
    name: &str,
    value: Value,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    match receiver {
        Value::Instance(inst) => {
            inst.borrow_mut().fields.insert(name.to_string(), value);
            Ok(Flow::nil())
        }
        Value::Class(class) => {
            // Walk the chain — `Child.staticField = …` should update the
            // declaring class so the change is visible to every sibling.
            if set_static_in_chain(class, name, value.clone()) {
                Ok(Flow::nil())
            } else {
                // Define a fresh static on the most-derived class.
                class
                    .static_fields
                    .borrow_mut()
                    .insert(name.to_string(), value);
                Ok(Flow::nil())
            }
        }
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot assign field `{name}` on value of type `{}` — only instances and classes can have fields assigned",
                other.type_name()
            ),
            span,
        }),
    }
}

fn set_static_in_chain(class: &Rc<crate::value::ClassObject>, name: &str, value: Value) -> bool {
    if class.static_fields.borrow().contains_key(name) {
        class
            .static_fields
            .borrow_mut()
            .insert(name.to_string(), value);
        return true;
    }
    if let Some(parent) = &class.parent {
        return set_static_in_chain(parent, name, value);
    }
    false
}

fn assign_index(
    receiver: &Value,
    index: Value,
    value: Value,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    match receiver {
        Value::Table(items) => {
            let Some(slot) = expr::table_index_to_slot(&index).map_err(|message| RuntimeError::TypeError {
                message,
                span: span.clone(),
            })? else {
                return Err(RuntimeError::TypeError {
                    message: "table assignment index must be a positive integer".to_string(),
                    span,
                });
            };

            let mut items = items.borrow_mut();
            if slot >= items.len() {
                items.resize(slot + 1, Value::Nil);
            }
            items[slot] = value;
            Ok(Flow::nil())
        }
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot assign through `[index]` on a `{}` — only tables support indexed assignment",
                other.type_name()
            ),
            span,
        }),
    }
}

// ─── Numeric for ─────────────────────────────────────────────────────────────

fn exec_for_numeric(
    var: &str,
    from: &Spanned<Expr>,
    to: &Spanned<Expr>,
    step: Option<&Spanned<Expr>>,
    body: &[Spanned<Stmt>],
    env: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    let from_v = expr::eval(from, env)?;
    let to_v = expr::eval(to, env)?;
    let step_v = match step {
        Some(e) => expr::eval(e, env)?,
        // Default step matches the loop's numeric type.
        None => match &from_v {
            Value::Float(_) => Value::Float(1.0),
            _ => Value::Int(1),
        },
    };

    match (from_v, to_v, step_v) {
        (Value::Int(f), Value::Int(t), Value::Int(s)) => {
            if s == 0 {
                return Err(RuntimeError::ZeroStep { span });
            }
            run_numeric_loop_int(var, f, t, s, body, env)
        }
        (Value::Float(f), Value::Float(t), Value::Float(s)) => {
            if s == 0.0 {
                return Err(RuntimeError::ZeroStep { span });
            }
            run_numeric_loop_float(var, f, t, s, body, env)
        }
        (f, t, s) => Err(RuntimeError::TypeError {
            message: format!(
                "numeric `for` loop requires all bounds (from, to, step) to be the same numeric type — got `{}`, `{}`, `{}` (use matching integer or float bounds)",
                f.type_name(),
                t.type_name(),
                s.type_name()
            ),
            span,
        }),
    }
}

fn run_numeric_loop_int(
    var: &str,
    from: i64,
    to: i64,
    step: i64,
    body: &[Spanned<Stmt>],
    parent: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let mut i = from;
    while (step > 0 && i <= to) || (step < 0 && i >= to) {
        let scope = Environment::with_parent(parent.clone());
        scope.borrow_mut().define(var.to_string(), Value::Int(i));
        match exec_block(body, &scope)? {
            Flow::Normal(_) | Flow::Continue => {}
            Flow::Break => return Ok(Flow::nil()),
            ret @ Flow::Return(_) => return Ok(ret),
        }
        // Detect overflow so a too-large step doesn't loop forever.
        let (next, overflow) = i.overflowing_add(step);
        if overflow {
            break;
        }
        i = next;
    }
    Ok(Flow::nil())
}

fn run_numeric_loop_float(
    var: &str,
    from: f64,
    to: f64,
    step: f64,
    body: &[Spanned<Stmt>],
    parent: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let mut i = from;
    while (step > 0.0 && i <= to) || (step < 0.0 && i >= to) {
        let scope = Environment::with_parent(parent.clone());
        scope.borrow_mut().define(var.to_string(), Value::Float(i));
        match exec_block(body, &scope)? {
            Flow::Normal(_) | Flow::Continue => {}
            Flow::Break => return Ok(Flow::nil()),
            ret @ Flow::Return(_) => return Ok(ret),
        }
        i += step;
    }
    Ok(Flow::nil())
}

fn exec_for_in(
    vars: &[(String, Option<saule_ast::Type>)],
    iter: &Spanned<Expr>,
    body: &[Spanned<Stmt>],
    env: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    let iter_value = expr::eval(iter, env)?;
    match iter_value {
        Value::Table(items) => {
            let snapshot = items.borrow().clone();
            for (i, value) in snapshot.into_iter().enumerate() {
                let scope = Environment::with_parent(env.clone());
                match vars {
                    [(name, _)] => {
                        scope.borrow_mut().define(name.clone(), value);
                    }
                    [(index_name, _), (value_name, _)] => {
                        scope
                            .borrow_mut()
                            .define(index_name.clone(), Value::Int((i + 1) as i64));
                        scope.borrow_mut().define(value_name.clone(), value);
                    }
                    _ => {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "for-in loops support one value variable or an index/value pair, got {} variables",
                                vars.len()
                            ),
                            span,
                        });
                    }
                }

                match exec_block(body, &scope)? {
                    Flow::Normal(_) | Flow::Continue => {}
                    Flow::Break => return Ok(Flow::nil()),
                    ret @ Flow::Return(_) => return Ok(ret),
                }
            }
            Ok(Flow::nil())
        }
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot iterate over a `{}` with `for ... in` — use a table value",
                other.type_name()
            ),
            span,
        }),
    }
}

//! Statement execution with control-flow propagation.

use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

use saule_ast::{ClassMember, Decl, EnumVariant, Expr, Method, Param, Spanned, Stmt};

use crate::env::Environment;
use crate::error::{RuntimeError, unsupported};
use crate::value::{self, ClassObject, FieldDef, FunctionBody, FunctionObject, Value};

use super::{Flow, expr};

/// Execute a sequence of statements in `env`. Stops at the first non-`Normal`
/// outcome and propagates it.
pub fn exec_block(
    stmts: &[Spanned<Stmt>],
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let mut last = Flow::nil();
    for stmt in stmts {
        match exec(stmt, env)? {
            Flow::Normal(v) => last = Flow::Normal(v),
            other => return Ok(other),
        }
    }
    Ok(last)
}

/// Run a block in a fresh child scope. The scope is dropped on return.
fn exec_scoped_block(
    stmts: &[Spanned<Stmt>],
    parent: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let scope = Environment::with_parent(parent.clone());
    exec_block(stmts, &scope)
}

/// Execute a single statement.
pub fn exec(stmt: &Spanned<Stmt>, env: &Rc<RefCell<Environment>>) -> Result<Flow, RuntimeError> {
    let span = stmt.span.clone();
    match &stmt.value {
        Stmt::Local { name, value, .. } => {
            let v = match value {
                Some(e) => expr::eval(e, env)?,
                None => Value::Nil,
            };
            env.borrow_mut().define(name.clone(), v);
            Ok(Flow::nil())
        }

        Stmt::LocalMulti { names, values } => {
            // Evaluate every RHS first so `local a, b = b, a` works at the
            // outer scope. The final expression may expand into multiple
            // return values (Lua-style destructuring semantics).
            let evaluated = eval_expr_list(values, env)?;
            for (i, (name, _)) in names.iter().enumerate() {
                let v = evaluated.get(i).cloned().unwrap_or(Value::Nil);
                env.borrow_mut().define(name.clone(), v);
            }
            Ok(Flow::nil())
        }

        Stmt::Assign { target, value } => exec_assign(target, value, env),

        Stmt::AssignMulti { targets, values } => {
            // Evaluate all RHS expressions first to support parallel
            // semantics (e.g. `a, b = b, a + b`). The final expression may
            // expand into multiple return values.
            let evaluated = eval_expr_list(values, env)?;
            for (i, target) in targets.iter().enumerate() {
                let v = evaluated.get(i).cloned().unwrap_or(Value::Nil);
                assign_target(target, v, env)?;
            }
            Ok(Flow::nil())
        }

        Stmt::Expr(e) => Ok(Flow::Normal(expr::eval(e, env)?)),

        Stmt::If {
            cond,
            then_block,
            elseifs,
            else_block,
        } => {
            if expr::eval(cond, env)?.is_truthy() {
                return exec_scoped_block(then_block, env);
            }
            for (econd, ebody) in elseifs {
                if expr::eval(econd, env)?.is_truthy() {
                    return exec_scoped_block(ebody, env);
                }
            }
            if let Some(eb) = else_block {
                return exec_scoped_block(eb, env);
            }
            Ok(Flow::nil())
        }

        Stmt::While { cond, body } => {
            while expr::eval(cond, env)?.is_truthy() {
                match exec_scoped_block(body, env)? {
                    Flow::Normal(_) | Flow::Continue => continue,
                    Flow::Break => break,
                    ret @ Flow::Return(_) => return Ok(ret),
                }
            }
            Ok(Flow::nil())
        }

        Stmt::Repeat { body, cond } => {
            // Lua semantics: the `until` condition sees locals declared in
            // the body, so condition and body must share the same scope.
            loop {
                let scope = Environment::with_parent(env.clone());
                match exec_block(body, &scope)? {
                    Flow::Normal(_) | Flow::Continue => {}
                    Flow::Break => break,
                    ret @ Flow::Return(_) => return Ok(ret),
                }
                if expr::eval(cond, &scope)?.is_truthy() {
                    break;
                }
            }
            Ok(Flow::nil())
        }

        Stmt::ForNumeric {
            var,
            var_ty: _,
            from,
            to,
            step,
            body,
        } => exec_for_numeric(var, from, to, step.as_ref(), body, env, span),

        Stmt::ForIn { vars, iter, body } => exec_for_in(vars, iter, body, env, span),

        Stmt::Return(exprs) => {
            let values = if exprs.is_empty() {
                vec![Value::Nil]
            } else {
                eval_expr_list(exprs, env)?
            };
            Ok(Flow::Return(values))
        }

        Stmt::Break => Ok(Flow::Break),
        Stmt::Continue => Ok(Flow::Continue),

        Stmt::Throw(_) => Err(unsupported("throw", span)),
        Stmt::Try { .. } => Err(unsupported("try/catch", span)),
        Stmt::Decl(decl) => exec_decl(decl, env),
    }
}

fn eval_expr_list(
    exprs: &[Spanned<Expr>],
    env: &Rc<RefCell<Environment>>,
) -> Result<Vec<Value>, RuntimeError> {
    let mut out = Vec::new();
    for (i, expr_node) in exprs.iter().enumerate() {
        if i + 1 == exprs.len() {
            out.extend(expr::eval_values(expr_node, env)?);
        } else {
            out.push(expr::eval(expr_node, env)?);
        }
    }
    Ok(out)
}

// ─── Declarations ────────────────────────────────────────────────────────────

fn exec_decl(
    decl: &Spanned<Decl>,
    env: &std::rc::Rc<std::cell::RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let span = decl.span.clone();
    match &decl.value {
        Decl::Function {
            name, params, body, ..
        } => {
            let func = FunctionObject {
                name: Some(name.clone()),
                params: params.clone(),
                body: FunctionBody::Block(body.clone()),
                closure: env.clone(),
            };
            env.borrow_mut()
                .define(name.clone(), Value::Function(std::rc::Rc::new(func)));
            Ok(Flow::nil())
        }
        Decl::Class { .. } => exec_class_decl(decl, env),
        Decl::Interface { .. } => Err(unsupported("interface declaration", span)),
        Decl::Enum { name, variants, methods, .. } => exec_enum_decl(name, variants, methods, env, span),
        Decl::Import { .. } => Err(unsupported("import", span)),
    }
}

/// Materialize a `Decl::Class` into a [`ClassObject`] and install it under
/// the class's name in `env`. Method closures all capture `env` so they can
/// see the class itself (used by static calls) and other top-level names.
fn exec_class_decl(
    decl: &Spanned<Decl>,
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let span = decl.span.clone();
    let Decl::Class {
        name,
        extends,
        members,
        ..
    } = &decl.value
    else {
        unreachable!("exec_class_decl called with non-class decl");
    };

    // Resolve parent class, if any. Must already exist in scope.
    let parent = if let Some(pname) = extends {
        match env.borrow().get(pname) {
            Some(Value::Class(c)) => Some(c),
            Some(other) => {
                return Err(RuntimeError::TypeError {
                    message: format!(
                        "cannot extend `{}`: expected a class but got `{}` — check class definition",
                        pname, other.type_name()
                    ),
                    span,
                });
            }
            None => {
                return Err(RuntimeError::Undefined {
                    name: pname.clone(),
                    span,
                });
            }
        }
    } else {
        None
    };

    let mut field_defs: Vec<FieldDef> = Vec::new();
    let mut methods: HashMap<String, Rc<FunctionObject>> = HashMap::new();
    let mut static_fields: HashMap<String, Value> = HashMap::new();
    let mut static_methods: HashMap<String, Rc<FunctionObject>> = HashMap::new();
    let mut constructor: Option<Rc<FunctionObject>> = None;

    // Scan once so we know whether the class has a constructor (`fn init`).
    // When it doesn't, `local field = expr` declarations are promoted to
    // statics so callers can read them via `ClassName.field` (and through
    // the class-as-`self` convention used inside `static fn`s).
    let has_init_method = members.iter().any(|m| match &m.value {
        ClassMember::Method(meth) => meth.name == "init" && !meth.is_static,
        _ => false,
    });

    for member in members {
        match &member.value {
            ClassMember::Field {
                is_static,
                name: fname,
                default,
                ..
            } => {
                // Promote `local field = expr` to a static when there's no
                // constructor — otherwise we'd never be able to read it.
                let treat_as_static = *is_static || (!has_init_method && default.is_some());
                if treat_as_static {
                    // Static defaults are evaluated once, at class
                    // declaration time, in the enclosing scope.
                    let value = match default {
                        Some(e) => expr::eval(e, env)?,
                        None => Value::Nil,
                    };
                    static_fields.insert(fname.clone(), value);
                } else {
                    field_defs.push(FieldDef {
                        name: fname.clone(),
                        default: default.clone(),
                    });
                }
            }
            ClassMember::Method(m) => {
                let func = Rc::new(make_function(
                    Some(format!("{name}.{}", m.name)),
                    m.params.clone(),
                    m.body.clone(),
                    env,
                ));
                if m.is_static {
                    static_methods.insert(m.name.clone(), func);
                } else if m.name == "init" {
                    // `init` is the only constructor spelling — always promote.
                    constructor = Some(func);
                } else {
                    methods.insert(m.name.clone(), func);
                }
            }
        }
    }

    let class = Rc::new(ClassObject {
        name: name.clone(),
        parent,
        field_defs,
        methods,
        static_fields: RefCell::new(static_fields),
        static_methods,
        constructor,
    });

    env.borrow_mut().define(name.clone(), Value::Class(class));
    Ok(Flow::nil())
}

fn make_function(
    name: Option<String>,
    params: Vec<Param>,
    body: Vec<Spanned<Stmt>>,
    closure: &Rc<RefCell<Environment>>,
) -> FunctionObject {
    let _ = closure; // silence unused if we change capture
    FunctionObject {
        name,
        params,
        body: FunctionBody::Block(body),
        closure: closure.clone(),
    }
}

fn exec_enum_decl(
    enum_name: &str,
    variants: &[Spanned<EnumVariant>],
    methods: &[Method],
    env: &Rc<RefCell<Environment>>,
    _span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    let mut variant_dict = HashMap::new();
    let mut enum_methods = HashMap::new();

    for method in methods {
        let func = Rc::new(make_function(
            Some(format!("{enum_name}.{}", method.name)),
            method.params.clone(),
            method.body.clone(),
            env,
        ));
        enum_methods.insert(method.name.clone(), func);
    }

    // Create all variants (without enum references initially)
    for variant in variants {
        match &variant.value {
            EnumVariant::Bare(name) => {
                let variant_obj = Rc::new(value::EnumVariantObject {
                    enum_name: enum_name.to_string(),
                    variant_name: name.clone(),
                    value: None,
                    enum_obj: RefCell::new(None),
                });
                variant_dict.insert(name.clone(), variant_obj);
            }
            EnumVariant::Valued(name, expr) => {
                let val = expr::eval(expr, env)?;
                let variant_obj = Rc::new(value::EnumVariantObject {
                    enum_name: enum_name.to_string(),
                    variant_name: name.clone(),
                    value: Some(val),
                    enum_obj: RefCell::new(None),
                });
                variant_dict.insert(name.clone(), variant_obj);
            }
        }
    }

    // Create the final enum object with all variants
    let final_enum = Rc::new(value::EnumObject {
        name: enum_name.to_string(),
        variants: variant_dict.clone(),
        methods: enum_methods,
    });

    // Now update each variant to reference the enum
    for variant in variant_dict.values() {
        *variant.enum_obj.borrow_mut() = Some(final_enum.clone());
    }

    env.borrow_mut()
        .define(enum_name.to_string(), Value::Enum(final_enum));
    Ok(Flow::nil())
}

// ─── Assignment ──────────────────────────────────────────────────────────────

fn exec_assign(
    target: &Spanned<Expr>,
    value: &Spanned<Expr>,
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let v = expr::eval(value, env)?;
    assign_target(target, v, env)
}

fn assign_target(
    target: &Spanned<Expr>,
    v: Value,
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    match &target.value {
        Expr::Ident(name) => {
            if env.borrow_mut().assign(name, v) {
                Ok(Flow::nil())
            } else {
                Err(RuntimeError::AssignUndeclared {
                    name: name.clone(),
                    span: target.span.clone(),
                })
            }
        }
        // `obj.field = v` / `Class.static = v`
        Expr::Member { obj, name } => {
            let receiver = expr::eval(obj, env)?;
            assign_member(&receiver, name, v, target.span.clone())
        }
        Expr::Index { obj, index } => {
            let receiver = expr::eval(obj, env)?;
            let index_value = expr::eval(index, env)?;
            assign_index(&receiver, index_value, v, target.span.clone())
        }
        _ => Err(RuntimeError::InvalidAssignTarget {
            span: target.span.clone(),
        }),
    }
}

fn assign_member(
    receiver: &Value,
    name: &str,
    value: Value,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    match receiver {
        Value::Instance(inst) => {
            inst.borrow_mut().fields.insert(name.to_string(), value);
            Ok(Flow::nil())
        }
        Value::Class(class) => {
            // Walk the chain — `Child.staticField = …` should update the
            // declaring class so the change is visible to every sibling.
            if set_static_in_chain(class, name, value.clone()) {
                Ok(Flow::nil())
            } else {
                // Define a fresh static on the most-derived class.
                class
                    .static_fields
                    .borrow_mut()
                    .insert(name.to_string(), value);
                Ok(Flow::nil())
            }
        }
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot assign field `{name}` on value of type `{}` — only instances and classes can have fields assigned",
                other.type_name()
            ),
            span,
        }),
    }
}

fn set_static_in_chain(class: &Rc<crate::value::ClassObject>, name: &str, value: Value) -> bool {
    if class.static_fields.borrow().contains_key(name) {
        class
            .static_fields
            .borrow_mut()
            .insert(name.to_string(), value);
        return true;
    }
    if let Some(parent) = &class.parent {
        return set_static_in_chain(parent, name, value);
    }
    false
}

fn assign_index(
    receiver: &Value,
    index: Value,
    value: Value,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    match receiver {
        Value::Table(items) => {
            let Some(slot) = expr::table_index_to_slot(&index).map_err(|message| RuntimeError::TypeError {
                message,
                span: span.clone(),
            })? else {
                return Err(RuntimeError::TypeError {
                    message: "table assignment index must be a positive integer".to_string(),
                    span,
                });
            };

            let mut items = items.borrow_mut();
            if slot >= items.len() {
                items.resize(slot + 1, Value::Nil);
            }
            items[slot] = value;
            Ok(Flow::nil())
        }
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot assign through `[index]` on a `{}` — only tables support indexed assignment",
                other.type_name()
            ),
            span,
        }),
    }
}

// ─── Numeric for ─────────────────────────────────────────────────────────────

fn exec_for_numeric(
    var: &str,
    from: &Spanned<Expr>,
    to: &Spanned<Expr>,
    step: Option<&Spanned<Expr>>,
    body: &[Spanned<Stmt>],
    env: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    let from_v = expr::eval(from, env)?;
    let to_v = expr::eval(to, env)?;
    let step_v = match step {
        Some(e) => expr::eval(e, env)?,
        // Default step matches the loop's numeric type.
        None => match &from_v {
            Value::Float(_) => Value::Float(1.0),
            _ => Value::Int(1),
        },
    };

    match (from_v, to_v, step_v) {
        (Value::Int(f), Value::Int(t), Value::Int(s)) => {
            if s == 0 {
                return Err(RuntimeError::ZeroStep { span });
            }
            run_numeric_loop_int(var, f, t, s, body, env)
        }
        (Value::Float(f), Value::Float(t), Value::Float(s)) => {
            if s == 0.0 {
                return Err(RuntimeError::ZeroStep { span });
            }
            run_numeric_loop_float(var, f, t, s, body, env)
        }
        (f, t, s) => Err(RuntimeError::TypeError {
            message: format!(
                "numeric `for` loop requires all bounds (from, to, step) to be the same numeric type — got `{}`, `{}`, `{}` (use matching integer or float bounds)",
                f.type_name(),
                t.type_name(),
                s.type_name()
            ),
            span,
        }),
    }
}

fn run_numeric_loop_int(
    var: &str,
    from: i64,
    to: i64,
    step: i64,
    body: &[Spanned<Stmt>],
    parent: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let mut i = from;
    while (step > 0 && i <= to) || (step < 0 && i >= to) {
        let scope = Environment::with_parent(parent.clone());
        scope.borrow_mut().define(var.to_string(), Value::Int(i));
        match exec_block(body, &scope)? {
            Flow::Normal(_) | Flow::Continue => {}
            Flow::Break => return Ok(Flow::nil()),
            ret @ Flow::Return(_) => return Ok(ret),
        }
        // Detect overflow so a too-large step doesn't loop forever.
        let (next, overflow) = i.overflowing_add(step);
        if overflow {
            break;
        }
        i = next;
    }
    Ok(Flow::nil())
}

fn run_numeric_loop_float(
    var: &str,
    from: f64,
    to: f64,
    step: f64,
    body: &[Spanned<Stmt>],
    parent: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let mut i = from;
    while (step > 0.0 && i <= to) || (step < 0.0 && i >= to) {
        let scope = Environment::with_parent(parent.clone());
        scope.borrow_mut().define(var.to_string(), Value::Float(i));
        match exec_block(body, &scope)? {
            Flow::Normal(_) | Flow::Continue => {}
            Flow::Break => return Ok(Flow::nil()),
            ret @ Flow::Return(_) => return Ok(ret),
        }
        i += step;
    }
    Ok(Flow::nil())
}

fn exec_for_in(
    vars: &[(String, Option<saule_ast::Type>)],
    iter: &Spanned<Expr>,
    body: &[Spanned<Stmt>],
    env: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    let iter_value = expr::eval(iter, env)?;
    match iter_value {
        Value::Table(items) => {
            let snapshot = items.borrow().clone();
            for (i, value) in snapshot.into_iter().enumerate() {
                let scope = Environment::with_parent(env.clone());
                match vars {
                    [(name, _)] => {
                        scope.borrow_mut().define(name.clone(), value);
                    }
                    [(index_name, _), (value_name, _)] => {
                        scope
                            .borrow_mut()
                            .define(index_name.clone(), Value::Int((i + 1) as i64));
                        scope.borrow_mut().define(value_name.clone(), value);
                    }
                    _ => {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "for-in loops support one value variable or an index/value pair, got {} variables",
                                vars.len()
                            ),
                            span,
                        });
                    }
                }

                match exec_block(body, &scope)? {
                    Flow::Normal(_) | Flow::Continue => {}
                    Flow::Break => return Ok(Flow::nil()),
                    ret @ Flow::Return(_) => return Ok(ret),
                }
            }
            Ok(Flow::nil())
        }
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot iterate over a `{}` with `for ... in` — use a table value",
                other.type_name()
            ),
            span,
        }),
    }
}

//! Runtime values for the Saule interpreter.
//!
//! When adding a new variant, remember to extend [`Value::type_name`],
//! [`Value::is_truthy`], [`Value::to_display_string`], and the `PartialEq`
//! impl below.

use std::cell::RefCell;
use std::collections::HashMap;
use std::fmt;
use std::rc::Rc;

use saule_ast::{Expr, Param, Spanned, Stmt};

use crate::env::Environment;

/// A Saule runtime value.
#[derive(Debug, Clone)]
pub enum Value {
    Nil,
    Bool(bool),
    Int(i64),
    Float(f64),
    /// Interned via `Rc` so cloning a value is cheap.
    Str(Rc<String>),
    /// Array-style table storage. Shared by reference so aliasing behaves like
    /// Lua tables and indexed mutation is visible through every alias.
    Table(Rc<RefCell<Vec<Value>>>),
    /// Built-in function written in Rust (e.g. `print`).
    Native(Rc<NativeFn>),
    /// User-defined function or lambda. The `Rc` makes cloning cheap and
    /// gives recursive closures something stable to point at.
    Function(Rc<FunctionObject>),
    /// A class declaration — carries its statics, instance template, and
    /// optional parent. Compared by identity.
    Class(Rc<ClassObject>),
    /// An instance produced by `new ClassName(args)`. Fields are mutable
    /// behind a `RefCell`; identity is the `Rc` pointer.
    Instance(Rc<RefCell<InstanceObject>>),
}

/// Rust-implemented function exposed to Saule.
///
/// The function returns `Result<Value, String>` where the error string is
/// surfaced as a `RuntimeError::TypeError` at the call site.
pub struct NativeFn {
    pub name: &'static str,
    pub func: fn(&[Value]) -> Result<Value, String>,
}

impl fmt::Debug for NativeFn {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "<native fn {}>", self.name)
    }
}

/// A user-defined function carrying its body and lexical closure.
#[derive(Debug)]
pub struct FunctionObject {
    /// `Some(name)` for named declarations, `None` for lambdas.
    pub name: Option<String>,
    pub params: Vec<Param>,
    pub body: FunctionBody,
    /// The environment that was in scope when the function was created.
    /// Captured by reference so inner functions see live bindings.
    pub closure: Rc<RefCell<Environment>>,
}

/// Function bodies come in two shapes:
///   * a block of statements (named `fn` decls, block-body lambdas),
///   * a single expression (arrow-style lambdas like `(x) => x + 1`).
#[derive(Debug, Clone)]
pub enum FunctionBody {
    Block(Vec<Spanned<Stmt>>),
    Expr(Box<Spanned<saule_ast::Expr>>),
}

/// Runtime representation of a `class` declaration.
///
/// Instance fields live on the [`InstanceObject`]; statics live here (behind
/// a `RefCell` because they can be reassigned). Methods are stored as
/// already-constructed [`FunctionObject`]s capturing the module-level
/// environment so they can refer to other top-level names (including the
/// class itself for static calls).
#[derive(Debug)]
pub struct ClassObject {
    pub name: String,
    pub parent: Option<Rc<ClassObject>>,
    /// Instance-field templates evaluated on construction.
    pub field_defs: Vec<FieldDef>,
    /// Instance methods, keyed by name. First parameter is the user-written
    /// `self`, so calling `obj:method(a)` is the same as `method(obj, a)`.
    pub methods: HashMap<String, Rc<FunctionObject>>,
    /// Static fields. Mutable through `ClassName.field = …`.
    pub static_fields: RefCell<HashMap<String, Value>>,
    /// Static methods (no implicit `self`).
    pub static_methods: HashMap<String, Rc<FunctionObject>>,
    /// `constructor(args) … end`. None means the class has no explicit
    /// constructor — `new` still produces a valid instance.
    pub constructor: Option<Rc<FunctionObject>>,
}

#[derive(Debug, Clone)]
pub struct FieldDef {
    pub name: String,
    /// Evaluated in the constructor scope each time an instance is built.
    pub default: Option<Spanned<Expr>>,
}

#[derive(Debug)]
pub struct InstanceObject {
    pub class: Rc<ClassObject>,
    pub fields: HashMap<String, Value>,
}

impl ClassObject {
    /// Walk the inheritance chain for a method.
    pub fn lookup_method(self: &Rc<Self>, name: &str) -> Option<Rc<FunctionObject>> {
        if let Some(m) = self.methods.get(name) {
            return Some(m.clone());
        }
        self.parent.as_ref().and_then(|p| p.lookup_method(name))
    }

    /// Walk the inheritance chain for a static method.
    pub fn lookup_static_method(self: &Rc<Self>, name: &str) -> Option<Rc<FunctionObject>> {
        if let Some(m) = self.static_methods.get(name) {
            return Some(m.clone());
        }
        self.parent
            .as_ref()
            .and_then(|p| p.lookup_static_method(name))
    }

    /// Walk the inheritance chain for a static field.
    pub fn lookup_static_field(self: &Rc<Self>, name: &str) -> Option<Value> {
        if let Some(v) = self.static_fields.borrow().get(name) {
            return Some(v.clone());
        }
        self.parent
            .as_ref()
            .and_then(|p| p.lookup_static_field(name))
    }
}

impl Value {
    /// Human-readable type name for error messages — matches the names used
    /// in the README's type system.
    pub fn type_name(&self) -> &'static str {
        match self {
            Value::Nil => "nil",
            Value::Bool(_) => "boolean",
            Value::Int(_) => "integer",
            Value::Float(_) => "float",
            Value::Str(_) => "string",
            Value::Table(_) => "table",
            Value::Native(_) | Value::Function(_) => "function",
            Value::Class(_) => "class",
            Value::Instance(_) => "instance",
        }
    }

    /// Lua-style truthiness: only `nil` and `false` are falsy.
    pub fn is_truthy(&self) -> bool {
        !matches!(self, Value::Nil | Value::Bool(false))
    }

    /// Format used by `print` and the `..` operator.
    pub fn to_display_string(&self) -> String {
        match self {
            Value::Nil => "nil".into(),
            Value::Bool(b) => b.to_string(),
            Value::Int(n) => n.to_string(),
            Value::Float(f) => {
                // Always show a decimal point so floats are visually distinct
                // from ints, matching the README's display style.
                if f.fract() == 0.0 && f.is_finite() {
                    format!("{f:.1}")
                } else {
                    f.to_string()
                }
            }
            Value::Str(s) => (**s).clone(),
            Value::Table(items) => {
                let parts: Vec<String> = items
                    .borrow()
                    .iter()
                    .map(Value::to_display_string)
                    .collect();
                format!("{{{}}}", parts.join(", "))
            }
            Value::Native(nf) => format!("<native fn {}>", nf.name),
            Value::Function(f) => match &f.name {
                Some(n) => format!("<fn {n}>"),
                None => "<lambda>".into(),
            },
            Value::Class(c) => format!("<class {}>", c.name),
            Value::Instance(i) => format!("<instance of {}>", i.borrow().class.name),
        }
    }
}

// Equality is used by tests and by the `==` / `~=` operators. Functions
// (native or user-defined) compare by identity.
impl PartialEq for Value {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Value::Nil, Value::Nil) => true,
            (Value::Bool(a), Value::Bool(b)) => a == b,
            (Value::Int(a), Value::Int(b)) => a == b,
            (Value::Float(a), Value::Float(b)) => a == b,
            (Value::Str(a), Value::Str(b)) => a == b,
            (Value::Table(a), Value::Table(b)) => Rc::ptr_eq(a, b),
            (Value::Native(a), Value::Native(b)) => Rc::ptr_eq(a, b),
            (Value::Function(a), Value::Function(b)) => Rc::ptr_eq(a, b),
            (Value::Class(a), Value::Class(b)) => Rc::ptr_eq(a, b),
            (Value::Instance(a), Value::Instance(b)) => Rc::ptr_eq(a, b),
            _ => false,
        }
    }
}

//! Runtime values for the Saule interpreter.
//!
//! When adding a new variant, remember to extend [`Value::type_name`],
//! [`Value::is_truthy`], [`Value::to_display_string`], and the `PartialEq`
//! impl below.

use std::cell::RefCell;
use std::collections::HashMap;
use std::fmt;
use std::rc::Rc;

use saule_ast::{Expr, Param, Spanned, Stmt};

use crate::env::Environment;

/// A Saule runtime value.
#[derive(Debug, Clone)]
pub enum Value {
    Nil,
    Bool(bool),
    Int(i64),
    Float(f64),
    /// Interned via `Rc` so cloning a value is cheap.
    Str(Rc<String>),
    /// Array-style table storage. Shared by reference so aliasing behaves like
    /// Lua tables and indexed mutation is visible through every alias.
    Table(Rc<RefCell<Vec<Value>>>),
    /// Built-in function written in Rust (e.g. `print`).
    Native(Rc<NativeFn>),
    /// User-defined function or lambda. The `Rc` makes cloning cheap and
    /// gives recursive closures something stable to point at.
    Function(Rc<FunctionObject>),
    /// A class declaration — carries its statics, instance template, and
    /// optional parent. Compared by identity.
    Class(Rc<ClassObject>),
    /// An instance produced by `new ClassName(args)`. Fields are mutable
    /// behind a `RefCell`; identity is the `Rc` pointer.
    Instance(Rc<RefCell<InstanceObject>>),
    /// An enum variant: carries the enum name, variant name, and optional
    /// value. Compared by identity so each access to `Status.Alive` returns
    /// the same `Rc` pointer.
    EnumVariant(Rc<EnumVariantObject>),
    /// An enum declaration — carries its variants and methods.
    Enum(Rc<EnumObject>),
}

#[derive(Debug)]
pub struct EnumVariantObject {
    pub enum_name: String,
    pub variant_name: String,
    pub value: Option<Value>,
    /// Reference to the enum so we can access methods. Stored in RefCell to
    /// allow updating after enum creation (breaking the circular reference issue).
    pub enum_obj: std::cell::RefCell<Option<Rc<EnumObject>>>,
}

#[derive(Debug)]
pub struct EnumObject {
    pub name: String,
    /// Enum variants, keyed by name. Each variant is cached so identity is stable.
    pub variants: HashMap<String, Rc<EnumVariantObject>>,
    /// Methods defined on the enum, keyed by name.
    pub methods: HashMap<String, Rc<FunctionObject>>,
}

/// Rust-implemented function exposed to Saule.
///
/// The function returns `Result<Value, String>` where the error string is
/// surfaced as a `RuntimeError::TypeError` at the call site.
pub struct NativeFn {
    pub name: &'static str,
    pub func: fn(&[Value]) -> Result<Value, String>,
}

impl fmt::Debug for NativeFn {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "<native fn {}>", self.name)
    }
}

/// A user-defined function carrying its body and lexical closure.
#[derive(Debug)]
pub struct FunctionObject {
    /// `Some(name)` for named declarations, `None` for lambdas.
    pub name: Option<String>,
    pub params: Vec<Param>,
    pub body: FunctionBody,
    /// The environment that was in scope when the function was created.
    /// Captured by reference so inner functions see live bindings.
    pub closure: Rc<RefCell<Environment>>,
}

/// Function bodies come in two shapes:
///   * a block of statements (named `fn` decls, block-body lambdas),
///   * a single expression (arrow-style lambdas like `(x) => x + 1`).
#[derive(Debug, Clone)]
pub enum FunctionBody {
    Block(Vec<Spanned<Stmt>>),
    Expr(Box<Spanned<saule_ast::Expr>>),
}

/// Runtime representation of a `class` declaration.
///
/// Instance fields live on the [`InstanceObject`]; statics live here (behind
/// a `RefCell` because they can be reassigned). Methods are stored as
/// already-constructed [`FunctionObject`]s capturing the module-level
/// environment so they can refer to other top-level names (including the
/// class itself for static calls).
#[derive(Debug)]
pub struct ClassObject {
    pub name: String,
    pub parent: Option<Rc<ClassObject>>,
    /// Instance-field templates evaluated on construction.
    pub field_defs: Vec<FieldDef>,
    /// Instance methods, keyed by name. First parameter is the user-written
    /// `self`, so calling `obj:method(a)` is the same as `method(obj, a)`.
    pub methods: HashMap<String, Rc<FunctionObject>>,
    /// Static fields. Mutable through `ClassName.field = …`.
    pub static_fields: RefCell<HashMap<String, Value>>,
    /// Static methods (no implicit `self`).
    pub static_methods: HashMap<String, Rc<FunctionObject>>,
    /// `constructor(args) … end`. None means the class has no explicit
    /// constructor — `new` still produces a valid instance.
    pub constructor: Option<Rc<FunctionObject>>,
}

#[derive(Debug, Clone)]
pub struct FieldDef {
    pub name: String,
    /// Evaluated in the constructor scope each time an instance is built.
    pub default: Option<Spanned<Expr>>,
}

#[derive(Debug)]
pub struct InstanceObject {
    pub class: Rc<ClassObject>,
    pub fields: HashMap<String, Value>,
}

impl ClassObject {
    /// Walk the inheritance chain for a method.
    pub fn lookup_method(self: &Rc<Self>, name: &str) -> Option<Rc<FunctionObject>> {
        if let Some(m) = self.methods.get(name) {
            return Some(m.clone());
        }
        self.parent.as_ref().and_then(|p| p.lookup_method(name))
    }

    /// Walk the inheritance chain for a static method.
    pub fn lookup_static_method(self: &Rc<Self>, name: &str) -> Option<Rc<FunctionObject>> {
        if let Some(m) = self.static_methods.get(name) {
            return Some(m.clone());
        }
        self.parent
            .as_ref()
            .and_then(|p| p.lookup_static_method(name))
    }

    /// Walk the inheritance chain for a static field.
    pub fn lookup_static_field(self: &Rc<Self>, name: &str) -> Option<Value> {
        if let Some(v) = self.static_fields.borrow().get(name) {
            return Some(v.clone());
        }
        self.parent
            .as_ref()
            .and_then(|p| p.lookup_static_field(name))
    }
}

impl Value {
    /// Human-readable type name for error messages — matches the names used
    /// in the README's type system.
    pub fn type_name(&self) -> &'static str {
        match self {
            Value::Nil => "nil",
            Value::Bool(_) => "boolean",
            Value::Int(_) => "integer",
            Value::Float(_) => "float",
            Value::Str(_) => "string",
            Value::Table(_) => "table",
            Value::Native(_) | Value::Function(_) => "function",
            Value::Class(_) => "class",
            Value::Instance(_) => "instance",
            Value::EnumVariant(_) => "enum",
            Value::Enum(_) => "enum",
        }
    }

    /// Lua-style truthiness: only `nil` and `false` are falsy.
    pub fn is_truthy(&self) -> bool {
        !matches!(self, Value::Nil | Value::Bool(false))
    }

    /// Format used by `print` and the `..` operator.
    pub fn to_display_string(&self) -> String {
        match self {
            Value::Nil => "nil".into(),
            Value::Bool(b) => b.to_string(),
            Value::Int(n) => n.to_string(),
            Value::Float(f) => {
                // Always show a decimal point so floats are visually distinct
                // from ints, matching the README's display style.
                if f.fract() == 0.0 && f.is_finite() {
                    format!("{f:.1}")
                } else {
                    f.to_string()
                }
            }
            Value::Str(s) => (**s).clone(),
            Value::Table(items) => {
                let parts: Vec<String> = items
                    .borrow()
                    .iter()
                    .map(Value::to_display_string)
                    .collect();
                format!("{{{}}}", parts.join(", "))
            }
            Value::EnumVariant(ev) => {
                format!("{}.{}", ev.enum_name, ev.variant_name)
            }
            Value::Enum(e) => format!("<enum {}>", e.name),
            Value::Native(nf) => format!("<native fn {}>", nf.name),
            Value::Function(f) => match &f.name {
                Some(n) => format!("<fn {n}>"),
                None => "<lambda>".into(),
            },
            Value::Class(c) => format!("<class {}>", c.name),
            Value::Instance(i) => format!("<instance of {}>", i.borrow().class.name),
        }
    }
}

// Equality is used by tests and by the `==` / `~=` operators. Functions
// (native or user-defined) compare by identity.
impl PartialEq for Value {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Value::Nil, Value::Nil) => true,
            (Value::Bool(a), Value::Bool(b)) => a == b,
            (Value::Int(a), Value::Int(b)) => a == b,
            (Value::Float(a), Value::Float(b)) => a == b,
            (Value::Str(a), Value::Str(b)) => a == b,
            (Value::Table(a), Value::Table(b)) => Rc::ptr_eq(a, b),
            (Value::Native(a), Value::Native(b)) => Rc::ptr_eq(a, b),
            (Value::Function(a), Value::Function(b)) => Rc::ptr_eq(a, b),
            (Value::Class(a), Value::Class(b)) => Rc::ptr_eq(a, b),
            (Value::Instance(a), Value::Instance(b)) => Rc::ptr_eq(a, b),
            (Value::EnumVariant(a), Value::EnumVariant(b)) => Rc::ptr_eq(a, b),
            (Value::Enum(a), Value::Enum(b)) => Rc::ptr_eq(a, b),
            _ => false,
        }
    }
}

//! Expression evaluation.

use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

use saule_ast::{BinOp, CallArg, Expr, LambdaBody, Spanned, Type};

use crate::env::Environment;
use crate::error::{RuntimeError, unsupported};
use crate::value::{ClassObject, FunctionBody, FunctionObject, InstanceObject, Value};

use super::{Flow, ops};

const SUPER_OWNER_BINDING: &str = "__saule_super_owner";

#[derive(Clone)]
pub(crate) enum EvaluatedArg {
    Positional(Value),
    Named { name: String, value: Value },
}

pub fn eval(expr: &Spanned<Expr>, env: &Rc<RefCell<Environment>>) -> Result<Value, RuntimeError> {
    let span = expr.span.clone();
    match &expr.value {
        Expr::Int(n) => Ok(Value::Int(*n)),
        Expr::Float(f) => Ok(Value::Float(*f)),
        Expr::Bool(b) => Ok(Value::Bool(*b)),
        Expr::Str(s) => Ok(Value::Str(Rc::new(s.clone()))),
        Expr::Nil => Ok(Value::Nil),

        Expr::Ident(name) => env
            .borrow()
            .get(name)
            .ok_or_else(|| RuntimeError::Undefined {
                name: name.clone(),
                span,
            }),

        Expr::Unary { op, rhs } => {
            let v = eval(rhs, env)?;
            ops::unary(*op, v, span)
        }

        Expr::Binary { op, lhs, rhs } => match op {
            // `and` / `or` short-circuit, so evaluate lazily.
            BinOp::And => {
                let l = eval(lhs, env)?;
                if l.is_truthy() { eval(rhs, env) } else { Ok(l) }
            }
            BinOp::Or => {
                let l = eval(lhs, env)?;
                if l.is_truthy() { Ok(l) } else { eval(rhs, env) }
            }
            _ => {
                let l = eval(lhs, env)?;
                let r = eval(rhs, env)?;
                ops::binary(*op, l, r, span)
            }
        },

        Expr::Call { callee, args } => {
            // Dotted calls (`obj.method(args)`) and `self.super(args)` need
            // special handling so we can auto-bind `self` and route to the
            // parent constructor respectively. Saule lets instance methods
            // omit the explicit `self` parameter — see `call_instance_method`.
            if let Expr::Member { obj, name } = &callee.value {
                if name == "super" {
                    return super_call(obj, args, env, span);
                }
                let receiver = eval(obj, env)?;
                let vs = eval_call_args(args, env)?;
                return dispatch_member_call(&receiver, name, vs, span);
            }

            let cv = eval(callee, env)?;
            let vs = eval_call_args(args, env)?;
            call_value(cv, &vs, span)
        }

        // Postfix / composite forms — wait until later phases.
        Expr::Member { obj, name } => {
            let receiver = eval(obj, env)?;
            read_member(&receiver, name, span)
        }
        Expr::SafeMember { .. } => Err(unsupported("safe member access", span)),
        Expr::Index { obj, index } => {
            let receiver = eval(obj, env)?;
            let index_value = eval(index, env)?;
            read_index(&receiver, index_value, span)
        }
        Expr::MethodCall { obj, method, args } => {
            let receiver = eval(obj, env)?;
            let evaled = eval_call_args(args, env)?;
            invoke_method(&receiver, method, evaled, span)
        }
        Expr::ForceUnwrap(_) => Err(unsupported("force unwrap", span)),
        Expr::New { class, args } => {
            let class_val = env
                .borrow()
                .get(class)
                .ok_or_else(|| RuntimeError::Undefined {
                    name: class.clone(),
                    span: span.clone(),
                })?;
            let class = match class_val {
                Value::Class(c) => c,
                other => {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "`new` requires a class name, but got a `{}` — did you mean to call a function instead?",
                            other.type_name()
                        ),
                        span,
                    });
                }
            };
            let mut vs = Vec::with_capacity(args.len());
            for a in args {
                vs.push(EvaluatedArg::Positional(eval(a, env)?));
            }
            construct(class, &vs, span)
        }
        Expr::Table(items) => {
            let mut values = Vec::with_capacity(items.len());
            for item in items {
                values.push(eval(item, env)?);
            }
            Ok(Value::Table(Rc::new(RefCell::new(values))))
        }

        Expr::Lambda { params, body, .. } => {
            let body = match body {
                LambdaBody::Expr(e) => FunctionBody::Expr(e.clone()),
                LambdaBody::Block(stmts) => FunctionBody::Block(stmts.clone()),
            };
            Ok(Value::Function(Rc::new(FunctionObject {
                name: None,
                params: params.clone(),
                body,
                closure: env.clone(),
            })))
        }

        Expr::Self_ => env
            .borrow()
            .get("self")
            .ok_or_else(|| RuntimeError::Undefined {
                name: "self".to_string(),
                span,
            }),
        Expr::Super => Err(unsupported("`super`", span)),
    }
}

fn first_or_nil(values: Vec<Value>) -> Value {
    values.into_iter().next().unwrap_or(Value::Nil)
}

pub(crate) fn eval_values(
    expr: &Spanned<Expr>,
    env: &Rc<RefCell<Environment>>,
) -> Result<Vec<Value>, RuntimeError> {
    let span = expr.span.clone();
    match &expr.value {
        Expr::Call { callee, args } => {
            if let Expr::Member { obj, name } = &callee.value {
                if name == "super" {
                    return Ok(vec![super_call(obj, args, env, span)?]);
                }
                let receiver = eval(obj, env)?;
                let vs = eval_call_args(args, env)?;
                return dispatch_member_call_multi(&receiver, name, vs, span);
            }

            let cv = eval(callee, env)?;
            let vs = eval_call_args(args, env)?;
            call_value_multi(cv, &vs, span)
        }
        Expr::MethodCall { obj, method, args } => {
            let receiver = eval(obj, env)?;
            let evaled = eval_call_args(args, env)?;
            invoke_method_multi(&receiver, method, evaled, span)
        }
        _ => Ok(vec![eval(expr, env)?]),
    }
}

/// Invoke a callable [`Value`]. Handles both native and user-defined
/// functions.
fn call_value(
    callee: Value,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(call_value_multi(callee, args, span)?))
}

fn call_value_multi(
    callee: Value,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    match callee {
        Value::Native(nf) => {
            let mut positional = Vec::with_capacity(args.len());
            for arg in args {
                match arg {
                    EvaluatedArg::Positional(v) => positional.push(v.clone()),
                    EvaluatedArg::Named { name: _, .. } => {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "named arguments are not supported for built-in function `{}` — use positional arguments instead",
                                nf.name
                            ),
                            span,
                        });
                    }
                }
            }
            (nf.func)(&positional)
                .map(|v| vec![v])
                .map_err(|message| RuntimeError::TypeError { message, span })
        }
        Value::Function(f) => call_function_multi(&f, args, span),
        // `ClassName(args)` is sugar for `new ClassName(args)`. The explicit
        // `new` form still works through `Expr::New`.
        Value::Class(c) => construct(c, args, span).map(|v| vec![v]),
        other => Err(RuntimeError::TypeError {
            message: format!(
                "value of type `{}` is not callable — only functions, classes, and methods can be called",
                other.type_name()
            ),
            span,
        }),
    }
}

/// Bind `params` into `scope` from `args`, evaluating defaults lazily. Used
/// by every kind of call (free function, instance method, static method,
/// constructor) so the rules stay in one place.
fn bind_params(
    scope: &Rc<RefCell<Environment>>,
    params: &[saule_ast::Param],
    args: &[EvaluatedArg],
    span: &std::ops::Range<usize>,
) -> Result<(), RuntimeError> {
    let variadic_indices: Vec<usize> = params
        .iter()
        .enumerate()
        .filter_map(|(i, p)| p.variadic.then_some(i))
        .collect();
    if variadic_indices.len() > 1 {
        return Err(RuntimeError::TypeError {
            message: "a function can declare at most one variadic parameter".to_string(),
            span: params[variadic_indices[1]].span.clone(),
        });
    }
    let variadic_idx = variadic_indices.first().copied();
    if let Some(idx) = variadic_idx
        && idx + 1 != params.len()
    {
        return Err(RuntimeError::TypeError {
            message: format!(
                "variadic parameter `{}` must be the last parameter in the list",
                params[idx].name
            ),
            span: params[idx].span.clone(),
        });
    }

    let mut assigned: Vec<Option<Value>> = vec![None; params.len()];
    let mut variadic_values: Vec<Value> = Vec::new();
    let mut next_positional = 0usize;
    let mut seen_named = false;
    let mut named_arg_count = 0usize;

    for arg in args {
        match arg {
            EvaluatedArg::Positional(value) => {
                if seen_named {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "positional argument #{} cannot follow named arguments; all positional arguments must come first",
                            next_positional + 1
                        ),
                        span: span.clone(),
                    });
                }
                if let Some(var_idx) = variadic_idx
                    && next_positional >= var_idx
                {
                    variadic_values.push(value.clone());
                    next_positional += 1;
                    continue;
                }
                if next_positional >= params.len() {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "too many arguments: expected {} but got at least {}",
                            params.len(),
                            next_positional + 1
                        ),
                        span: span.clone(),
                    });
                }
                assigned[next_positional] = Some(value.clone());
                next_positional += 1;
            }
            EvaluatedArg::Named { name, value } => {
                seen_named = true;
                named_arg_count += 1;
                let Some(idx) = params.iter().position(|p| p.name == *name) else {
                    let valid_params: Vec<String> = params.iter().map(|p| p.name.clone()).collect();
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "unknown named argument `{name}` (argument #{} of {}) — valid parameters: {}",
                            named_arg_count,
                            args.len(),
                            valid_params.join(", ")
                        ),
                        span: span.clone(),
                    });
                };
                if params[idx].variadic {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "variadic parameter `{name}` cannot be passed by name — provide any extra arguments positionally"
                        ),
                        span: span.clone(),
                    });
                }
                if assigned[idx].is_some() {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "duplicate argument for parameter `{name}` — this parameter was already provided"
                        ),
                        span: span.clone(),
                    });
                }
                assigned[idx] = Some(value.clone());
            }
        }
    }

    let missing_required: Vec<String> = params
        .iter()
        .enumerate()
        .filter_map(|(i, p)| {
            if assigned[i].is_none()
                && !p.variadic
                && p.default.is_none()
                && !is_nullable_type(&p.ty)
            {
                Some(p.name.clone())
            } else {
                None
            }
        })
        .collect();

    for (i, param) in params.iter().enumerate() {
        if param.variadic {
            scope.borrow_mut().define(
                param.name.clone(),
                Value::Table(Rc::new(RefCell::new(variadic_values.clone()))),
            );
            continue;
        }
        let value = if let Some(v) = assigned[i].clone() {
            v
        } else if let Some(default) = &param.default {
            eval(default, scope)?
        } else if is_nullable_type(&param.ty) {
            Value::Nil
        } else {
            return Err(RuntimeError::TypeError {
                message: if missing_required.len() == 1 {
                    format!("missing required argument for parameter `{}`", param.name)
                } else {
                    format!(
                        "missing {} required argument(s): {}",
                        missing_required.len(),
                        missing_required.join(", ")
                    )
                },
                span: span.clone(),
            });
        };
        scope.borrow_mut().define(param.name.clone(), value);
    }
    Ok(())
}

fn is_nullable_type(ty: &Type) -> bool {
    matches!(ty, Type::Nullable(_)) || matches!(ty, Type::Named(n) if n == "nil")
}

pub(crate) fn table_index_to_slot(index: &Value) -> Result<Option<usize>, String> {
    match index {
        Value::Int(i) if *i <= 0 => Ok(None),
        Value::Int(i) => Ok(Some((*i as usize) - 1)),
        other => Err(format!(
            "table indices must be integers, got `{}`",
            other.type_name()
        )),
    }
}

fn read_index(
    receiver: &Value,
    index: Value,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    match receiver {
        Value::Table(items) => {
            let Some(slot) = table_index_to_slot(&index).map_err(|message| RuntimeError::TypeError {
                message,
                span: span.clone(),
            })? else {
                return Ok(Value::Nil);
            };
            Ok(items.borrow().get(slot).cloned().unwrap_or(Value::Nil))
        }
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot index a `{}` — only tables support `[index]` access",
                other.type_name()
            ),
            span,
        }),
    }
}

fn eval_call_args(
    args: &[CallArg],
    env: &Rc<RefCell<Environment>>,
) -> Result<Vec<EvaluatedArg>, RuntimeError> {
    let mut out = Vec::with_capacity(args.len());
    for arg in args {
        match arg {
            CallArg::Positional(expr) => out.push(EvaluatedArg::Positional(eval(expr, env)?)),
            CallArg::Named { name, value } => out.push(EvaluatedArg::Named {
                name: name.clone(),
                value: eval(value, env)?,
            }),
        }
    }
    Ok(out)
}

fn run_function_body(
    f: &FunctionObject,
    scope: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(run_function_body_multi(f, scope, span)?))
}

fn run_function_body_multi(
    f: &FunctionObject,
    scope: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let outcome = match &f.body {
        FunctionBody::Block(stmts) => super::stmt::exec_block(stmts, scope)?,
        FunctionBody::Expr(e) => Flow::Return(vec![eval(e, scope)?]),
    };
    match outcome {
        Flow::Return(values) => Ok(values),
        Flow::Normal(_) => Ok(vec![Value::Nil]),
        Flow::Break => Err(RuntimeError::LoopControlOutsideLoop {
            which: "break",
            span,
        }),
        Flow::Continue => Err(RuntimeError::LoopControlOutsideLoop {
            which: "continue",
            span,
        }),
    }
}

/// Skip a leading `self` parameter (so explicit-self style still works
/// alongside the implicit-self style this language prefers).
fn user_params(f: &FunctionObject) -> &[saule_ast::Param] {
    if f.params.first().map(|p| p.name == "self").unwrap_or(false) {
        &f.params[1..]
    } else {
        &f.params
    }
}

/// Call a user-defined function: binds args (with defaults), executes the
/// body in a fresh scope parented to the function's closure, and converts
/// the resulting [`Flow`] into a return value.
pub(crate) fn call_function(
    f: &FunctionObject,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(call_function_multi(f, args, span)?))
}

fn call_function_multi(
    f: &FunctionObject,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let scope = Environment::with_parent(f.closure.clone());
    bind_params(&scope, &f.params, args, &span)?;
    run_function_body_multi(f, &scope, span)
}

fn call_instance_method_multi(
    f: &FunctionObject,
    receiver: Value,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let scope = Environment::with_parent(f.closure.clone());
    // Inject the class's static fields/methods so the method body can refer
    // to them by their bare names — see `inject_class_statics` for why.
    if let Value::Instance(inst) = &receiver {
        inject_class_statics(&scope, &inst.borrow().class);
    }
    scope.borrow_mut().define("self".to_string(), receiver);
    bind_params(&scope, user_params(f), args, &span)?;
    run_function_body_multi(f, &scope, span)
}

/// Invoke a static method with `self` bound to the class itself, which is
/// what makes `self.staticField` inside a `static fn` resolve to the right
/// thing (and is the only way `Main.main()` can reach `Main.lauris`).
fn call_static_method(
    f: &FunctionObject,
    class: &Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(call_static_method_multi(f, class, args, span)?))
}

fn call_static_method_multi(
    f: &FunctionObject,
    class: &Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let scope = Environment::with_parent(f.closure.clone());
    inject_class_statics(&scope, class);
    scope
        .borrow_mut()
        .define("self".to_string(), Value::Class(class.clone()));
    bind_params(&scope, user_params(f), args, &span)?;
    run_function_body_multi(f, &scope, span)
}

/// Make the class's static fields and methods directly visible inside a
/// method body, so users can write `lauris.introduce()` instead of
/// `self.lauris.introduce()` or `Main.lauris.introduce()`. Parent statics
/// are seeded first and overridden by child statics, matching the lookup
/// order used for member access. Locals and parameters bound later still
/// shadow these, so the user can introduce a same-named local without
/// surprise.
fn inject_class_statics(scope: &Rc<RefCell<Environment>>, class: &Rc<ClassObject>) {
    // Collect the chain root-first so the most-derived class wins.
    let mut chain: Vec<Rc<ClassObject>> = Vec::new();
    let mut cur = Some(class.clone());
    while let Some(c) = cur {
        chain.push(c.clone());
        cur = c.parent.clone();
    }
    for c in chain.iter().rev() {
        for (n, v) in c.static_fields.borrow().iter() {
            scope.borrow_mut().define(n.clone(), v.clone());
        }
        for (n, f) in &c.static_methods {
            scope
                .borrow_mut()
                .define(n.clone(), Value::Function(f.clone()));
        }
    }
}

/// Public re-export of [`call_static_method`] for embedders. Kept as a thin
/// wrapper so the implementation details (param binding, `self` injection)
/// stay private to this module.
pub(crate) fn call_static_method_public(
    f: &FunctionObject,
    class: &Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    call_static_method(f, class, args, span)
}

/// Resolve `obj.name(args)` where the lookup intent is to *invoke* the
/// result. Instance methods get implicit `self`; static methods get the
/// class as `self`; non-function fields are simply invoked through
/// [`call_value`].
fn dispatch_member_call(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(dispatch_member_call_multi(receiver, name, args, span)?))
}

fn dispatch_member_call_multi(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    match receiver {
        Value::Instance(inst) => {
            let class = inst.borrow().class.clone();
            if let Some(m) = class.lookup_method(name) {
                return call_instance_method_multi(&m, receiver.clone(), &args, span);
            }
            if let Some(m) = class.lookup_static_method(name) {
                return call_static_method_multi(&m, &class, &args, span);
            }
            // Fall back: maybe the instance has a callable field.
            if let Some(v) = inst.borrow().fields.get(name).cloned() {
                return call_value_multi(v, &args, span);
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no method or field `{name}` on instance of class `{}` — instance members are case-sensitive",
                    class.name
                ),
                span,
            })
        }
        Value::Class(class) => {
            if let Some(m) = class.lookup_static_method(name) {
                return call_static_method_multi(&m, class, &args, span);
            }
            if let Some(v) = class.lookup_static_field(name) {
                return call_value_multi(v, &args, span);
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no static member `{name}` on class `{}` — check the class definition for the correct name",
                    class.name
                ),
                span,
            })
        }
        Value::EnumVariant(_variant) => {
            // Look up the method in the enum's method list, then call with
            // self bound to the variant.
            let v = read_member(receiver, name, span.clone())?;
            match v {
                Value::Function(m) => {
                    call_instance_method_multi(&m, receiver.clone(), &args, span)
                }
                _ => call_value_multi(v, &args, span),
            }
        }
        _ => {
            // Generic: read the field, then call it.
            let v = read_member(receiver, name, span.clone())?;
            call_value_multi(v, &args, span)
        }
    }
}

/// `self.super(args)` — call the parent class's constructor on the current
/// instance. The receiver expression must evaluate to an instance whose
/// class has a parent.
fn super_call(
    obj: &Spanned<Expr>,
    args: &[CallArg],
    env: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    let receiver = eval(obj, env)?;
    let inst = match receiver {
        Value::Instance(i) => i,
        other => {
            return Err(RuntimeError::TypeError {
                message: format!(
                    "`super(...)` requires `self` (an instance receiver), but got a `{}` — use `self.super(...)` inside a constructor",
                    other.type_name()
                ),
                span,
            });
        }
    };
    let owner_class = super_owner_class(env).unwrap_or_else(|| inst.borrow().class.clone());
    let parent = owner_class
        .parent
        .clone()
        .ok_or_else(|| RuntimeError::TypeError {
            message: format!(
                "class `{}` has no parent to call `super` on",
                owner_class.name
            ),
            span: span.clone(),
        })?;
    let ctor = constructor_chain(&parent).ok_or_else(|| RuntimeError::TypeError {
        message: format!("parent class `{}` has no constructor", parent.name),
        span: span.clone(),
    })?;

    let vs = eval_super_args(args, env, &span)?;

    let scope = Environment::with_parent(ctor.closure.clone());
    scope
        .borrow_mut()
        .define("self".to_string(), Value::Instance(inst));
    scope.borrow_mut().define(
        SUPER_OWNER_BINDING.to_string(),
        Value::Class(parent.clone()),
    );
    bind_params(&scope, user_params(&ctor), &vs, &span)?;
    run_function_body(&ctor, &scope, span).map(|_| Value::Nil)
}

fn eval_super_args(
    args: &[CallArg],
    env: &Rc<RefCell<Environment>>,
    span: &std::ops::Range<usize>,
) -> Result<Vec<EvaluatedArg>, RuntimeError> {
    let mut out = Vec::with_capacity(args.len());
    for arg in args {
        match arg {
            CallArg::Positional(expr) => out.push(EvaluatedArg::Positional(eval(expr, env)?)),
            CallArg::Named { .. } => {
                return Err(RuntimeError::TypeError {
                    message: "named arguments are not supported in `super(...)`".to_string(),
                    span: span.clone(),
                });
            }
        }
    }
    Ok(out)
}

fn super_owner_class(env: &Rc<RefCell<Environment>>) -> Option<Rc<ClassObject>> {
    match env.borrow().get(SUPER_OWNER_BINDING) {
        Some(Value::Class(c)) => Some(c),
        _ => None,
    }
}

// ─── Class / instance helpers ───────────────────────────────────────────────

/// Read `receiver.name`.
///
/// On an instance:
///   1. instance fields,
///   2. class methods (returned as a `Function` — useful for `obj.method`
///      access, though most call sites use the `obj:method()` form),
///   3. class static fields (so `instance.maxHealth` still works the same
///      as `Class.maxHealth`).
///
/// On a class:
///   1. static fields,
///   2. static methods.
fn read_member(
    receiver: &Value,
    name: &str,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    match receiver {
        Value::Instance(inst) => {
            let inst_ref = inst.borrow();
            if let Some(v) = inst_ref.fields.get(name) {
                return Ok(v.clone());
            }
            if let Some(m) = inst_ref.class.lookup_method(name) {
                return Ok(Value::Function(m));
            }
            if let Some(v) = inst_ref.class.lookup_static_field(name) {
                return Ok(v);
            }
            if let Some(m) = inst_ref.class.lookup_static_method(name) {
                return Ok(Value::Function(m));
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no field or method `{name}` on instance of class `{}` — available fields: (check class definition)",
                    inst_ref.class.name
                ),
                span,
            })
        }
        Value::Class(class) => {
            if let Some(v) = class.lookup_static_field(name) {
                return Ok(v);
            }
            if let Some(m) = class.lookup_static_method(name) {
                return Ok(Value::Function(m));
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no static member `{name}` on class `{}` — try `{}:` method notation or check if this is an instance method",
                    class.name,
                    class.name
                ),
                span,
            })
        }
        Value::Enum(enum_obj) => {
            if let Some(variant) = enum_obj.variants.get(name) {
                return Ok(Value::EnumVariant(variant.clone()));
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no variant `{name}` on enum `{}` — check enum definition",
                    enum_obj.name
                ),
                span,
            })
        }
        Value::EnumVariant(variant) => {
            match name {
                "value" => {
                    Ok(variant
                        .value
                        .clone()
                        .unwrap_or(Value::Str(Rc::new(variant.variant_name.clone()))))
                }
                "name" => {
                    Ok(Value::Str(Rc::new(variant.variant_name.clone())))
                }
                _ => {
                    if let Some(enum_obj) = &variant.enum_obj {
                        if let Some(m) = enum_obj.methods.get(name) {
                            return Ok(Value::Function(m.clone()));
                        }
                    }
                    Err(RuntimeError::TypeError {
                        message: format!(
                            "no property or method `{name}` on enum variant `{}.{}`",
                            variant.enum_name, variant.variant_name
                        ),
                        span,
                    })
                }
            }
        }
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot read field `{name}` on value of type `{}` — only instances, classes, and enums have members",
                other.type_name()
            ),
            span,
        }),
    }
}

/// Dispatch `receiver:name(args)`. For instances we prepend `self`; for
/// classes we call the static method as-is.
/// Dispatch `receiver:name(args)` (the colon-call form). Delegates to the
/// shared [`dispatch_member_call`] so the dot and colon forms behave the
/// same way at runtime.
fn invoke_method(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    dispatch_member_call(receiver, name, args, span)
}

fn invoke_method_multi(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    dispatch_member_call_multi(receiver, name, args, span)
}

/// `new Class(args)` — create an instance, populate field defaults, then
/// run the constructor (if any) with `self` bound to the new object.
pub(crate) fn construct(
    class: Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    // Allocate the instance up-front so the constructor can stash it as
    // `self` and observe its own writes.
    let inst = Rc::new(RefCell::new(InstanceObject {
        class: class.clone(),
        fields: HashMap::new(),
    }));

    // Initialize instance fields from defaults (walking the inheritance
    // chain parent-first so the most-derived defaults win).
    init_fields(&class, &inst, &span)?;

    // Run the constructor — first declared on this class, otherwise the
    // nearest parent's. If none exists, fields stay at their defaults.
    if let Some(ctor) = constructor_chain(&class) {
        let scope = Environment::with_parent(ctor.closure.clone());
        inject_class_statics(&scope, &class);
        scope
            .borrow_mut()
            .define("self".to_string(), Value::Instance(inst.clone()));
        scope
            .borrow_mut()
            .define(SUPER_OWNER_BINDING.to_string(), Value::Class(class.clone()));
        // Skip a leading explicit `self` parameter if present (the
        // constructor / `init` body uses the auto-bound one).
        bind_params(&scope, user_params(&ctor), args, &span)?;
        run_function_body(&ctor, &scope, span)?;
    }

    Ok(Value::Instance(inst))
}

fn init_fields(
    class: &Rc<ClassObject>,
    inst: &Rc<RefCell<InstanceObject>>,
    span: &std::ops::Range<usize>,
) -> Result<(), RuntimeError> {
    if let Some(parent) = &class.parent {
        init_fields(parent, inst, span)?;
    }
    // Field-default expressions evaluate in the class's declaration scope.
    // We approximate by using the constructor's closure (every method on a
    // class shares that closure), falling back to a fresh prelude-less env
    // when none exists.
    let scope = if let Some(ctor) = &class.constructor {
        Environment::with_parent(ctor.closure.clone())
    } else if let Some(m) = class.methods.values().next() {
        Environment::with_parent(m.closure.clone())
    } else if let Some(m) = class.static_methods.values().next() {
        Environment::with_parent(m.closure.clone())
    } else {
        Environment::new()
    };
    // `self` is visible to default expressions too.
    scope
        .borrow_mut()
        .define("self".to_string(), Value::Instance(inst.clone()));

    for field in &class.field_defs {
        let value = match &field.default {
            Some(e) => eval(e, &scope)?,
            None => Value::Nil,
        };
        inst.borrow_mut().fields.insert(field.name.clone(), value);
    }
    Ok(())
}

fn constructor_chain(class: &Rc<ClassObject>) -> Option<Rc<FunctionObject>> {
    if let Some(c) = &class.constructor {
        return Some(c.clone());
    }
    class.parent.as_ref().and_then(constructor_chain)
}

//! Expression evaluation.

use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

use saule_ast::{BinOp, CallArg, Expr, LambdaBody, Spanned, Type};

use crate::env::Environment;
use crate::error::{RuntimeError, unsupported};
use crate::value::{ClassObject, FunctionBody, FunctionObject, InstanceObject, Value};

use super::{Flow, ops};

const SUPER_OWNER_BINDING: &str = "__saule_super_owner";

#[derive(Clone)]
pub(crate) enum EvaluatedArg {
    Positional(Value),
    Named { name: String, value: Value },
}

pub fn eval(expr: &Spanned<Expr>, env: &Rc<RefCell<Environment>>) -> Result<Value, RuntimeError> {
    let span = expr.span.clone();
    match &expr.value {
        Expr::Int(n) => Ok(Value::Int(*n)),
        Expr::Float(f) => Ok(Value::Float(*f)),
        Expr::Bool(b) => Ok(Value::Bool(*b)),
        Expr::Str(s) => Ok(Value::Str(Rc::new(s.clone()))),
        Expr::Nil => Ok(Value::Nil),

        Expr::Ident(name) => env
            .borrow()
            .get(name)
            .ok_or_else(|| RuntimeError::Undefined {
                name: name.clone(),
                span,
            }),

        Expr::Unary { op, rhs } => {
            let v = eval(rhs, env)?;
            ops::unary(*op, v, span)
        }

        Expr::Binary { op, lhs, rhs } => match op {
            // `and` / `or` short-circuit, so evaluate lazily.
            BinOp::And => {
                let l = eval(lhs, env)?;
                if l.is_truthy() { eval(rhs, env) } else { Ok(l) }
            }
            BinOp::Or => {
                let l = eval(lhs, env)?;
                if l.is_truthy() { Ok(l) } else { eval(rhs, env) }
            }
            _ => {
                let l = eval(lhs, env)?;
                let r = eval(rhs, env)?;
                ops::binary(*op, l, r, span)
            }
        },

        Expr::Call { callee, args } => {
            // Dotted calls (`obj.method(args)`) and `self.super(args)` need
            // special handling so we can auto-bind `self` and route to the
            // parent constructor respectively. Saule lets instance methods
            // omit the explicit `self` parameter — see `call_instance_method`.
            if let Expr::Member { obj, name } = &callee.value {
                if name == "super" {
                    return super_call(obj, args, env, span);
                }
                let receiver = eval(obj, env)?;
                let vs = eval_call_args(args, env)?;
                return dispatch_member_call(&receiver, name, vs, span);
            }

            let cv = eval(callee, env)?;
            let vs = eval_call_args(args, env)?;
            call_value(cv, &vs, span)
        }

        // Postfix / composite forms — wait until later phases.
        Expr::Member { obj, name } => {
            let receiver = eval(obj, env)?;
            read_member(&receiver, name, span)
        }
        Expr::SafeMember { .. } => Err(unsupported("safe member access", span)),
        Expr::Index { obj, index } => {
            let receiver = eval(obj, env)?;
            let index_value = eval(index, env)?;
            read_index(&receiver, index_value, span)
        }
        Expr::MethodCall { obj, method, args } => {
            let receiver = eval(obj, env)?;
            let evaled = eval_call_args(args, env)?;
            invoke_method(&receiver, method, evaled, span)
        }
        Expr::ForceUnwrap(_) => Err(unsupported("force unwrap", span)),
        Expr::New { class, args } => {
            let class_val = env
                .borrow()
                .get(class)
                .ok_or_else(|| RuntimeError::Undefined {
                    name: class.clone(),
                    span: span.clone(),
                })?;
            let class = match class_val {
                Value::Class(c) => c,
                other => {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "`new` requires a class name, but got a `{}` — did you mean to call a function instead?",
                            other.type_name()
                        ),
                        span,
                    });
                }
            };
            let mut vs = Vec::with_capacity(args.len());
            for a in args {
                vs.push(EvaluatedArg::Positional(eval(a, env)?));
            }
            construct(class, &vs, span)
        }
        Expr::Table(items) => {
            let mut values = Vec::with_capacity(items.len());
            for item in items {
                values.push(eval(item, env)?);
            }
            Ok(Value::Table(Rc::new(RefCell::new(values))))
        }

        Expr::Lambda { params, body, .. } => {
            let body = match body {
                LambdaBody::Expr(e) => FunctionBody::Expr(e.clone()),
                LambdaBody::Block(stmts) => FunctionBody::Block(stmts.clone()),
            };
            Ok(Value::Function(Rc::new(FunctionObject {
                name: None,
                params: params.clone(),
                body,
                closure: env.clone(),
            })))
        }

        Expr::Self_ => env
            .borrow()
            .get("self")
            .ok_or_else(|| RuntimeError::Undefined {
                name: "self".to_string(),
                span,
            }),
        Expr::Super => Err(unsupported("`super`", span)),
    }
}

fn first_or_nil(values: Vec<Value>) -> Value {
    values.into_iter().next().unwrap_or(Value::Nil)
}

pub(crate) fn eval_values(
    expr: &Spanned<Expr>,
    env: &Rc<RefCell<Environment>>,
) -> Result<Vec<Value>, RuntimeError> {
    let span = expr.span.clone();
    match &expr.value {
        Expr::Call { callee, args } => {
            if let Expr::Member { obj, name } = &callee.value {
                if name == "super" {
                    return Ok(vec![super_call(obj, args, env, span)?]);
                }
                let receiver = eval(obj, env)?;
                let vs = eval_call_args(args, env)?;
                return dispatch_member_call_multi(&receiver, name, vs, span);
            }

            let cv = eval(callee, env)?;
            let vs = eval_call_args(args, env)?;
            call_value_multi(cv, &vs, span)
        }
        Expr::MethodCall { obj, method, args } => {
            let receiver = eval(obj, env)?;
            let evaled = eval_call_args(args, env)?;
            invoke_method_multi(&receiver, method, evaled, span)
        }
        _ => Ok(vec![eval(expr, env)?]),
    }
}

/// Invoke a callable [`Value`]. Handles both native and user-defined
/// functions.
fn call_value(
    callee: Value,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(call_value_multi(callee, args, span)?))
}

fn call_value_multi(
    callee: Value,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    match callee {
        Value::Native(nf) => {
            let mut positional = Vec::with_capacity(args.len());
            for arg in args {
                match arg {
                    EvaluatedArg::Positional(v) => positional.push(v.clone()),
                    EvaluatedArg::Named { name: _, .. } => {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "named arguments are not supported for built-in function `{}` — use positional arguments instead",
                                nf.name
                            ),
                            span,
                        });
                    }
                }
            }
            (nf.func)(&positional)
                .map(|v| vec![v])
                .map_err(|message| RuntimeError::TypeError { message, span })
        }
        Value::Function(f) => call_function_multi(&f, args, span),
        // `ClassName(args)` is sugar for `new ClassName(args)`. The explicit
        // `new` form still works through `Expr::New`.
        Value::Class(c) => construct(c, args, span).map(|v| vec![v]),
        other => Err(RuntimeError::TypeError {
            message: format!(
                "value of type `{}` is not callable — only functions, classes, and methods can be called",
                other.type_name()
            ),
            span,
        }),
    }
}

/// Bind `params` into `scope` from `args`, evaluating defaults lazily. Used
/// by every kind of call (free function, instance method, static method,
/// constructor) so the rules stay in one place.
fn bind_params(
    scope: &Rc<RefCell<Environment>>,
    params: &[saule_ast::Param],
    args: &[EvaluatedArg],
    span: &std::ops::Range<usize>,
) -> Result<(), RuntimeError> {
    let variadic_indices: Vec<usize> = params
        .iter()
        .enumerate()
        .filter_map(|(i, p)| p.variadic.then_some(i))
        .collect();
    if variadic_indices.len() > 1 {
        return Err(RuntimeError::TypeError {
            message: "a function can declare at most one variadic parameter".to_string(),
            span: params[variadic_indices[1]].span.clone(),
        });
    }
    let variadic_idx = variadic_indices.first().copied();
    if let Some(idx) = variadic_idx
        && idx + 1 != params.len()
    {
        return Err(RuntimeError::TypeError {
            message: format!(
                "variadic parameter `{}` must be the last parameter in the list",
                params[idx].name
            ),
            span: params[idx].span.clone(),
        });
    }

    let mut assigned: Vec<Option<Value>> = vec![None; params.len()];
    let mut variadic_values: Vec<Value> = Vec::new();
    let mut next_positional = 0usize;
    let mut seen_named = false;
    let mut named_arg_count = 0usize;

    for arg in args {
        match arg {
            EvaluatedArg::Positional(value) => {
                if seen_named {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "positional argument #{} cannot follow named arguments; all positional arguments must come first",
                            next_positional + 1
                        ),
                        span: span.clone(),
                    });
                }
                if let Some(var_idx) = variadic_idx
                    && next_positional >= var_idx
                {
                    variadic_values.push(value.clone());
                    next_positional += 1;
                    continue;
                }
                if next_positional >= params.len() {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "too many arguments: expected {} but got at least {}",
                            params.len(),
                            next_positional + 1
                        ),
                        span: span.clone(),
                    });
                }
                assigned[next_positional] = Some(value.clone());
                next_positional += 1;
            }
            EvaluatedArg::Named { name, value } => {
                seen_named = true;
                named_arg_count += 1;
                let Some(idx) = params.iter().position(|p| p.name == *name) else {
                    let valid_params: Vec<String> = params.iter().map(|p| p.name.clone()).collect();
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "unknown named argument `{name}` (argument #{} of {}) — valid parameters: {}",
                            named_arg_count,
                            args.len(),
                            valid_params.join(", ")
                        ),
                        span: span.clone(),
                    });
                };
                if params[idx].variadic {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "variadic parameter `{name}` cannot be passed by name — provide any extra arguments positionally"
                        ),
                        span: span.clone(),
                    });
                }
                if assigned[idx].is_some() {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "duplicate argument for parameter `{name}` — this parameter was already provided"
                        ),
                        span: span.clone(),
                    });
                }
                assigned[idx] = Some(value.clone());
            }
        }
    }

    let missing_required: Vec<String> = params
        .iter()
        .enumerate()
        .filter_map(|(i, p)| {
            if assigned[i].is_none()
                && !p.variadic
                && p.default.is_none()
                && !is_nullable_type(&p.ty)
            {
                Some(p.name.clone())
            } else {
                None
            }
        })
        .collect();

    for (i, param) in params.iter().enumerate() {
        if param.variadic {
            scope.borrow_mut().define(
                param.name.clone(),
                Value::Table(Rc::new(RefCell::new(variadic_values.clone()))),
            );
            continue;
        }
        let value = if let Some(v) = assigned[i].clone() {
            v
        } else if let Some(default) = &param.default {
            eval(default, scope)?
        } else if is_nullable_type(&param.ty) {
            Value::Nil
        } else {
            return Err(RuntimeError::TypeError {
                message: if missing_required.len() == 1 {
                    format!("missing required argument for parameter `{}`", param.name)
                } else {
                    format!(
                        "missing {} required argument(s): {}",
                        missing_required.len(),
                        missing_required.join(", ")
                    )
                },
                span: span.clone(),
            });
        };
        scope.borrow_mut().define(param.name.clone(), value);
    }
    Ok(())
}

fn is_nullable_type(ty: &Type) -> bool {
    matches!(ty, Type::Nullable(_)) || matches!(ty, Type::Named(n) if n == "nil")
}

pub(crate) fn table_index_to_slot(index: &Value) -> Result<Option<usize>, String> {
    match index {
        Value::Int(i) if *i <= 0 => Ok(None),
        Value::Int(i) => Ok(Some((*i as usize) - 1)),
        other => Err(format!(
            "table indices must be integers, got `{}`",
            other.type_name()
        )),
    }
}

fn read_index(
    receiver: &Value,
    index: Value,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    match receiver {
        Value::Table(items) => {
            let Some(slot) = table_index_to_slot(&index).map_err(|message| RuntimeError::TypeError {
                message,
                span: span.clone(),
            })? else {
                return Ok(Value::Nil);
            };
            Ok(items.borrow().get(slot).cloned().unwrap_or(Value::Nil))
        }
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot index a `{}` — only tables support `[index]` access",
                other.type_name()
            ),
            span,
        }),
    }
}

fn eval_call_args(
    args: &[CallArg],
    env: &Rc<RefCell<Environment>>,
) -> Result<Vec<EvaluatedArg>, RuntimeError> {
    let mut out = Vec::with_capacity(args.len());
    for arg in args {
        match arg {
            CallArg::Positional(expr) => out.push(EvaluatedArg::Positional(eval(expr, env)?)),
            CallArg::Named { name, value } => out.push(EvaluatedArg::Named {
                name: name.clone(),
                value: eval(value, env)?,
            }),
        }
    }
    Ok(out)
}

fn run_function_body(
    f: &FunctionObject,
    scope: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(run_function_body_multi(f, scope, span)?))
}

fn run_function_body_multi(
    f: &FunctionObject,
    scope: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let outcome = match &f.body {
        FunctionBody::Block(stmts) => super::stmt::exec_block(stmts, scope)?,
        FunctionBody::Expr(e) => Flow::Return(vec![eval(e, scope)?]),
    };
    match outcome {
        Flow::Return(values) => Ok(values),
        Flow::Normal(_) => Ok(vec![Value::Nil]),
        Flow::Break => Err(RuntimeError::LoopControlOutsideLoop {
            which: "break",
            span,
        }),
        Flow::Continue => Err(RuntimeError::LoopControlOutsideLoop {
            which: "continue",
            span,
        }),
    }
}

/// Skip a leading `self` parameter (so explicit-self style still works
/// alongside the implicit-self style this language prefers).
fn user_params(f: &FunctionObject) -> &[saule_ast::Param] {
    if f.params.first().map(|p| p.name == "self").unwrap_or(false) {
        &f.params[1..]
    } else {
        &f.params
    }
}

/// Call a user-defined function: binds args (with defaults), executes the
/// body in a fresh scope parented to the function's closure, and converts
/// the resulting [`Flow`] into a return value.
pub(crate) fn call_function(
    f: &FunctionObject,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(call_function_multi(f, args, span)?))
}

fn call_function_multi(
    f: &FunctionObject,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let scope = Environment::with_parent(f.closure.clone());
    bind_params(&scope, &f.params, args, &span)?;
    run_function_body_multi(f, &scope, span)
}

fn call_instance_method_multi(
    f: &FunctionObject,
    receiver: Value,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let scope = Environment::with_parent(f.closure.clone());
    // Inject the class's static fields/methods so the method body can refer
    // to them by their bare names — see `inject_class_statics` for why.
    if let Value::Instance(inst) = &receiver {
        inject_class_statics(&scope, &inst.borrow().class);
    }
    scope.borrow_mut().define("self".to_string(), receiver);
    bind_params(&scope, user_params(f), args, &span)?;
    run_function_body_multi(f, &scope, span)
}

/// Invoke a static method with `self` bound to the class itself, which is
/// what makes `self.staticField` inside a `static fn` resolve to the right
/// thing (and is the only way `Main.main()` can reach `Main.lauris`).
fn call_static_method(
    f: &FunctionObject,
    class: &Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(call_static_method_multi(f, class, args, span)?))
}

fn call_static_method_multi(
    f: &FunctionObject,
    class: &Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let scope = Environment::with_parent(f.closure.clone());
    inject_class_statics(&scope, class);
    scope
        .borrow_mut()
        .define("self".to_string(), Value::Class(class.clone()));
    bind_params(&scope, user_params(f), args, &span)?;
    run_function_body_multi(f, &scope, span)
}

/// Make the class's static fields and methods directly visible inside a
/// method body, so users can write `lauris.introduce()` instead of
/// `self.lauris.introduce()` or `Main.lauris.introduce()`. Parent statics
/// are seeded first and overridden by child statics, matching the lookup
/// order used for member access. Locals and parameters bound later still
/// shadow these, so the user can introduce a same-named local without
/// surprise.
fn inject_class_statics(scope: &Rc<RefCell<Environment>>, class: &Rc<ClassObject>) {
    // Collect the chain root-first so the most-derived class wins.
    let mut chain: Vec<Rc<ClassObject>> = Vec::new();
    let mut cur = Some(class.clone());
    while let Some(c) = cur {
        chain.push(c.clone());
        cur = c.parent.clone();
    }
    for c in chain.iter().rev() {
        for (n, v) in c.static_fields.borrow().iter() {
            scope.borrow_mut().define(n.clone(), v.clone());
        }
        for (n, f) in &c.static_methods {
            scope
                .borrow_mut()
                .define(n.clone(), Value::Function(f.clone()));
        }
    }
}

/// Public re-export of [`call_static_method`] for embedders. Kept as a thin
/// wrapper so the implementation details (param binding, `self` injection)
/// stay private to this module.
pub(crate) fn call_static_method_public(
    f: &FunctionObject,
    class: &Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    call_static_method(f, class, args, span)
}

/// Resolve `obj.name(args)` where the lookup intent is to *invoke* the
/// result. Instance methods get implicit `self`; static methods get the
/// class as `self`; non-function fields are simply invoked through
/// [`call_value`].
fn dispatch_member_call(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(dispatch_member_call_multi(receiver, name, args, span)?))
}

fn dispatch_member_call_multi(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    match receiver {
        Value::Instance(inst) => {
            let class = inst.borrow().class.clone();
            if let Some(m) = class.lookup_method(name) {
                return call_instance_method_multi(&m, receiver.clone(), &args, span);
            }
            if let Some(m) = class.lookup_static_method(name) {
                return call_static_method_multi(&m, &class, &args, span);
            }
            // Fall back: maybe the instance has a callable field.
            if let Some(v) = inst.borrow().fields.get(name).cloned() {
                return call_value_multi(v, &args, span);
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no method or field `{name}` on instance of class `{}` — instance members are case-sensitive",
                    class.name
                ),
                span,
            })
        }
        Value::Class(class) => {
            if let Some(m) = class.lookup_static_method(name) {
                return call_static_method_multi(&m, class, &args, span);
            }
            if let Some(v) = class.lookup_static_field(name) {
                return call_value_multi(v, &args, span);
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no static member `{name}` on class `{}` — check the class definition for the correct name",
                    class.name
                ),
                span,
            })
        }
        Value::EnumVariant(_variant) => {
            // Look up the method in the enum's method list, then call with
            // self bound to the variant.
            let v = read_member(receiver, name, span.clone())?;
            match v {
                Value::Function(m) => {
                    call_instance_method_multi(&m, receiver.clone(), &args, span)
                }
                _ => call_value_multi(v, &args, span),
            }
        }
        _ => {
            // Generic: read the field, then call it.
            let v = read_member(receiver, name, span.clone())?;
            call_value_multi(v, &args, span)
        }
    }
}

/// `self.super(args)` — call the parent class's constructor on the current
/// instance. The receiver expression must evaluate to an instance whose
/// class has a parent.
fn super_call(
    obj: &Spanned<Expr>,
    args: &[CallArg],
    env: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    let receiver = eval(obj, env)?;
    let inst = match receiver {
        Value::Instance(i) => i,
        other => {
            return Err(RuntimeError::TypeError {
                message: format!(
                    "`super(...)` requires `self` (an instance receiver), but got a `{}` — use `self.super(...)` inside a constructor",
                    other.type_name()
                ),
                span,
            });
        }
    };
    let owner_class = super_owner_class(env).unwrap_or_else(|| inst.borrow().class.clone());
    let parent = owner_class
        .parent
        .clone()
        .ok_or_else(|| RuntimeError::TypeError {
            message: format!(
                "class `{}` has no parent to call `super` on",
                owner_class.name
            ),
            span: span.clone(),
        })?;
    let ctor = constructor_chain(&parent).ok_or_else(|| RuntimeError::TypeError {
        message: format!("parent class `{}` has no constructor", parent.name),
        span: span.clone(),
    })?;

    let vs = eval_super_args(args, env, &span)?;

    let scope = Environment::with_parent(ctor.closure.clone());
    scope
        .borrow_mut()
        .define("self".to_string(), Value::Instance(inst));
    scope.borrow_mut().define(
        SUPER_OWNER_BINDING.to_string(),
        Value::Class(parent.clone()),
    );
    bind_params(&scope, user_params(&ctor), &vs, &span)?;
    run_function_body(&ctor, &scope, span).map(|_| Value::Nil)
}

fn eval_super_args(
    args: &[CallArg],
    env: &Rc<RefCell<Environment>>,
    span: &std::ops::Range<usize>,
) -> Result<Vec<EvaluatedArg>, RuntimeError> {
    let mut out = Vec::with_capacity(args.len());
    for arg in args {
        match arg {
            CallArg::Positional(expr) => out.push(EvaluatedArg::Positional(eval(expr, env)?)),
            CallArg::Named { .. } => {
                return Err(RuntimeError::TypeError {
                    message: "named arguments are not supported in `super(...)`".to_string(),
                    span: span.clone(),
                });
            }
        }
    }
    Ok(out)
}

fn super_owner_class(env: &Rc<RefCell<Environment>>) -> Option<Rc<ClassObject>> {
    match env.borrow().get(SUPER_OWNER_BINDING) {
        Some(Value::Class(c)) => Some(c),
        _ => None,
    }
}

// ─── Class / instance helpers ───────────────────────────────────────────────

/// Read `receiver.name`.
///
/// On an instance:
///   1. instance fields,
///   2. class methods (returned as a `Function` — useful for `obj.method`
///      access, though most call sites use the `obj:method()` form),
///   3. class static fields (so `instance.maxHealth` still works the same
///      as `Class.maxHealth`).
///
/// On a class:
///   1. static fields,
///   2. static methods.
fn read_member(
    receiver: &Value,
    name: &str,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    match receiver {
        Value::Instance(inst) => {
            let inst_ref = inst.borrow();
            if let Some(v) = inst_ref.fields.get(name) {
                return Ok(v.clone());
            }
            if let Some(m) = inst_ref.class.lookup_method(name) {
                return Ok(Value::Function(m));
            }
            if let Some(v) = inst_ref.class.lookup_static_field(name) {
                return Ok(v);
            }
            if let Some(m) = inst_ref.class.lookup_static_method(name) {
                return Ok(Value::Function(m));
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no field or method `{name}` on instance of class `{}` — available fields: (check class definition)",
                    inst_ref.class.name
                ),
                span,
            })
        }
        Value::Class(class) => {
            if let Some(v) = class.lookup_static_field(name) {
                return Ok(v);
            }
            if let Some(m) = class.lookup_static_method(name) {
                return Ok(Value::Function(m));
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no static member `{name}` on class `{}` — try `{}:` method notation or check if this is an instance method",
                    class.name,
                    class.name
                ),
                span,
            })
        }
        Value::Enum(enum_obj) => {
            if let Some(variant) = enum_obj.variants.get(name) {
                return Ok(Value::EnumVariant(variant.clone()));
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no variant `{name}` on enum `{}` — check enum definition",
                    enum_obj.name
                ),
                span,
            })
        }
        Value::EnumVariant(variant) => {
            match name {
                "value" => {
                    Ok(variant
                        .value
                        .clone()
                        .unwrap_or(Value::Str(Rc::new(variant.variant_name.clone()))))
                }
                "name" => {
                    Ok(Value::Str(Rc::new(variant.variant_name.clone())))
                }
                _ => {
                    if let Some(enum_obj) = variant.enum_obj.borrow().as_ref() {
                        if let Some(m) = enum_obj.methods.get(name) {
                            return Ok(Value::Function(m.clone()));
                        }
                    }
                    Err(RuntimeError::TypeError {
                        message: format!(
                            "no property or method `{name}` on enum variant `{}.{}`",
                            variant.enum_name, variant.variant_name
                        ),
                        span,
                    })
                }
            }
        }
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot read field `{name}` on value of type `{}` — only instances, classes, and enums have members",
                other.type_name()
            ),
            span,
        }),
    }
}

/// Dispatch `receiver:name(args)`. For instances we prepend `self`; for
/// classes we call the static method as-is.
/// Dispatch `receiver:name(args)` (the colon-call form). Delegates to the
/// shared [`dispatch_member_call`] so the dot and colon forms behave the
/// same way at runtime.
fn invoke_method(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    dispatch_member_call(receiver, name, args, span)
}

fn invoke_method_multi(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    dispatch_member_call_multi(receiver, name, args, span)
}

/// `new Class(args)` — create an instance, populate field defaults, then
/// run the constructor (if any) with `self` bound to the new object.
pub(crate) fn construct(
    class: Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    // Allocate the instance up-front so the constructor can stash it as
    // `self` and observe its own writes.
    let inst = Rc::new(RefCell::new(InstanceObject {
        class: class.clone(),
        fields: HashMap::new(),
    }));

    // Initialize instance fields from defaults (walking the inheritance
    // chain parent-first so the most-derived defaults win).
    init_fields(&class, &inst, &span)?;

    // Run the constructor — first declared on this class, otherwise the
    // nearest parent's. If none exists, fields stay at their defaults.
    if let Some(ctor) = constructor_chain(&class) {
        let scope = Environment::with_parent(ctor.closure.clone());
        inject_class_statics(&scope, &class);
        scope
            .borrow_mut()
            .define("self".to_string(), Value::Instance(inst.clone()));
        scope
            .borrow_mut()
            .define(SUPER_OWNER_BINDING.to_string(), Value::Class(class.clone()));
        // Skip a leading explicit `self` parameter if present (the
        // constructor / `init` body uses the auto-bound one).
        bind_params(&scope, user_params(&ctor), args, &span)?;
        run_function_body(&ctor, &scope, span)?;
    }

    Ok(Value::Instance(inst))
}

fn init_fields(
    class: &Rc<ClassObject>,
    inst: &Rc<RefCell<InstanceObject>>,
    span: &std::ops::Range<usize>,
) -> Result<(), RuntimeError> {
    if let Some(parent) = &class.parent {
        init_fields(parent, inst, span)?;
    }
    // Field-default expressions evaluate in the class's declaration scope.
    // We approximate by using the constructor's closure (every method on a
    // class shares that closure), falling back to a fresh prelude-less env
    // when none exists.
    let scope = if let Some(ctor) = &class.constructor {
        Environment::with_parent(ctor.closure.clone())
    } else if let Some(m) = class.methods.values().next() {
        Environment::with_parent(m.closure.clone())
    } else if let Some(m) = class.static_methods.values().next() {
        Environment::with_parent(m.closure.clone())
    } else {
        Environment::new()
    };
    // `self` is visible to default expressions too.
    scope
        .borrow_mut()
        .define("self".to_string(), Value::Instance(inst.clone()));

    for field in &class.field_defs {
        let value = match &field.default {
            Some(e) => eval(e, &scope)?,
            None => Value::Nil,
        };
        inst.borrow_mut().fields.insert(field.name.clone(), value);
    }
    Ok(())
}

fn constructor_chain(class: &Rc<ClassObject>) -> Option<Rc<FunctionObject>> {
    if let Some(c) = &class.constructor {
        return Some(c.clone());
    }
    class.parent.as_ref().and_then(constructor_chain)
}

//! Tree-walking interpreter for the Saule language.
//!
//! Module layout:
//!
//! | Module       | Responsibility                              |
//! |--------------|---------------------------------------------|
//! | [`value`]    | Runtime [`Value`] enum and `NativeFn`       |
//! | [`env`]      | Lexical scopes ([`Environment`])            |
//! | [`builtins`] | Standard library installed into the prelude |
//! | [`error`]    | [`RuntimeError`] (miette-aware diagnostics) |
//! | [`eval`]     | Statement & expression evaluation           |
//!
//! Phase status:
//!   * Phase 1 — literals, locals, arithmetic, native calls (✓)
//!   * Phase 2 — assignment, blocks, `if`/`while`/`repeat`/numeric `for`,
//!     `break`/`continue`, lexical scoping (✓)
//!   * Phase 3 — user-defined functions, lambdas, closures, `return` (✓ —
//!     this commit)
//!   * Phase 4 — tables and indexing (next)

use std::cell::RefCell;
use std::rc::Rc;

use saule_ast::Module;

pub mod builtins;
pub mod env;
pub mod error;
pub mod eval;
pub mod typeck;
pub mod value;

pub use env::Environment;
pub use error::RuntimeError;
pub use eval::Flow;
pub use value::{NativeFn, Value};

/// Invoke a [`value::FunctionObject`] with the given arguments. Exposed so
/// embedders (the CLI, the REPL, future test runners) can call functions
/// that were defined in user code without re-parsing.
pub fn call_function_value(
    f: &std::rc::Rc<value::FunctionObject>,
    args: &[Value],
) -> Result<Value, RuntimeError> {
    let evaled: Vec<eval::expr::EvaluatedArg> = args
        .iter()
        .cloned()
        .map(eval::expr::EvaluatedArg::Positional)
        .collect();
    eval::expr::call_function(f, &evaled, 0..0)
}

/// Invoke a static method on a class, with `self` bound to the class — the
/// CLI uses this to run `Main.main()`.
pub fn call_class_static_method(
    class: &std::rc::Rc<value::ClassObject>,
    method: &str,
    args: &[Value],
) -> Result<Value, RuntimeError> {
    let f = class.lookup_static_method(method).ok_or_else(|| {
        RuntimeError::TypeError {
            message: format!("no static method `{method}` on class `{}`", class.name),
            span: 0..0,
        }
    })?;
    let evaled: Vec<eval::expr::EvaluatedArg> = args
        .iter()
        .cloned()
        .map(eval::expr::EvaluatedArg::Positional)
        .collect();
    eval::expr::call_static_method_public(&f, class, &evaled, 0..0)
}

/// Run a parsed [`Module`] in a fresh environment seeded with built-ins.
///
/// Returns the value of the last evaluated expression-statement (useful for
/// the REPL and for tests).
pub fn run(module: &Module) -> Result<Value, RuntimeError> {
    let env = Environment::with_prelude();
    run_in(module, &env)
}

/// Run a [`Module`] inside a caller-supplied environment.
pub fn run_in(module: &Module, env: &Rc<RefCell<Environment>>) -> Result<Value, RuntimeError> {
    match eval::stmt::exec_block(&module.stmts, env)? {
        Flow::Normal(v) => Ok(v),
        // At the top level these are illegal — `Stmt::Return` is rejected
        // inside `exec`; `break`/`continue` reach here only if they appear
        // outside any loop.
        Flow::Break => Err(RuntimeError::LoopControlOutsideLoop {
            which: "break",
            span: 0..0,
        }),
        Flow::Continue => Err(RuntimeError::LoopControlOutsideLoop {
            which: "continue",
            span: 0..0,
        }),
        Flow::Return(v) => Ok(v),
    }
}

// ─── Tests ───────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;
    use saule_lexer::Lexer;
    use saule_parser::parse;
    use std::rc::Rc;

    fn eval(src: &str) -> Result<Value, RuntimeError> {
        let toks = Lexer::new(src).tokenize().expect("lex");
        let module = parse(toks).expect("parse");
        run(&module)
    }

    // ── Phase 1 regression coverage ──────────────────────────────────────────

    #[test]
    fn integer_arithmetic() {
        assert_eq!(eval("1 + 2 * 3").unwrap(), Value::Int(7));
    }

    #[test]
    fn float_arithmetic() {
        match eval("1.5 + 2.5").unwrap() {
            Value::Float(f) => assert_eq!(f, 4.0),
            v => panic!("expected float, got {v:?}"),
        }
    }

    #[test]
    fn mixing_int_and_float_errors() {
        assert!(matches!(
            eval("1 + 2.0").unwrap_err(),
            RuntimeError::NumericMix { .. }
        ));
    }

    #[test]
    fn local_then_lookup() {
        assert_eq!(
            eval("local x: integer = 10\nx * 2").unwrap(),
            Value::Int(20)
        );
    }

    #[test]
    fn string_concat_and_length() {
        assert_eq!(
            eval(r#""foo" .. "bar""#).unwrap(),
            Value::Str(Rc::new("foobar".into()))
        );
        assert_eq!(eval(r#"#"hello""#).unwrap(), Value::Int(5));
    }

    #[test]
    fn comparison_and_logic() {
        assert_eq!(eval("1 < 2 and 3 >= 3").unwrap(), Value::Bool(true));
        assert_eq!(
            eval(r#"nil or "fallback""#).unwrap(),
            Value::Str(Rc::new("fallback".into()))
        );
    }

    #[test]
    fn null_coalescing() {
        assert_eq!(
            eval(r#"nil ?? "x""#).unwrap(),
            Value::Str(Rc::new("x".into()))
        );
        assert_eq!(
            eval(r#""y" ?? "x""#).unwrap(),
            Value::Str(Rc::new("y".into()))
        );
    }

    #[test]
    fn print_native_call() {
        assert_eq!(eval(r#"print("hello", 1, true)"#).unwrap(), Value::Nil);
    }

    #[test]
    fn undefined_variable_errors() {
        assert!(matches!(
            eval("nope").unwrap_err(),
            RuntimeError::Undefined { .. }
        ));
    }

    #[test]
    fn division_by_zero() {
        assert!(matches!(
            eval("1 / 0").unwrap_err(),
            RuntimeError::DivisionByZero { .. }
        ));
    }

    #[test]
    fn type_builtin() {
        assert_eq!(eval("type(42)").unwrap(), Value::Str(Rc::new("integer".into())));
        assert_eq!(eval(r#"type("hi")"#).unwrap(), Value::Str(Rc::new("string".into())));
    }

    // ── Phase 2: assignment ──────────────────────────────────────────────────

    #[test]
    fn assignment_updates_local() {
        let src = "local x: integer = 1\nx = x + 41\nx";
        assert_eq!(eval(src).unwrap(), Value::Int(42));
    }

    #[test]
    fn assign_to_undeclared_errors() {
        let src = "x = 1";
        assert!(matches!(
            eval(src).unwrap_err(),
            RuntimeError::AssignUndeclared { .. }
        ));
    }

    // ── Phase 2: if / elseif / else ──────────────────────────────────────────

    #[test]
    fn if_then_branch() {
        let src = r#"
            local x: integer = 0
            if true then
              x = 1
            else
              x = 2
            end
            x
        "#;
        assert_eq!(eval(src).unwrap(), Value::Int(1));
    }

    #[test]
    fn if_elseif_else_chain() {
        let src = r#"
            local n: integer = 7
            local kind: string = ""
            if n < 0 then
              kind = "neg"
            else if n == 0 then
              kind = "zero"
            else if n < 10 then
              kind = "small"
            else
              kind = "big"
            end
            kind
        "#;
        assert_eq!(eval(src).unwrap(), Value::Str(Rc::new("small".into())));
    }

    #[test]
    fn if_body_introduces_scope() {
        // `tmp` is declared inside the `if` body and must NOT leak out.
        let src = r#"
            local x: integer = 0
            if true then
              local tmp: integer = 9
              x = tmp
            end
            tmp
        "#;
        assert!(matches!(
            eval(src).unwrap_err(),
            RuntimeError::Undefined { .. }
        ));
    }

    // ── Phase 2: while + break + continue ────────────────────────────────────

    #[test]
    fn while_counts_to_ten() {
        let src = r#"
            local i: integer = 0
            local sum: integer = 0
            while i < 10 do
              i = i + 1
              sum = sum + i
            end
            return sum
        "#;
        assert_eq!(eval(src).unwrap(), Value::Int(55));
    }

    #[test]
    fn break_exits_loop_early() {
        let src = r#"
            local i: integer = 0
            while true do
              i = i + 1
              if i == 5 then
                break
              end
            end
            return i
        "#;
        assert_eq!(eval(src).unwrap(), Value::Int(5));
    }

    #[test]
    fn continue_skips_rest_of_iteration() {
        // Sum of odd numbers 1..=9 = 25.
        let src = r#"
            local i: integer = 0
            local sum: integer = 0
            while i < 10 do
              i = i + 1
              if i % 2 == 0 then
                continue
              end
              sum = sum + i
            end
            return sum
        "#;
        assert_eq!(eval(src).unwrap(), Value::Int(25));
    }

    // ── Phase 2: repeat / until ──────────────────────────────────────────────

    #[test]
    fn repeat_until_runs_at_least_once() {
        let src = r#"
            local i: integer = 0
            repeat
              i = i + 1
            until i >= 3
            return i
        "#;
        assert_eq!(eval(src).unwrap(), Value::Int(3));
    }

    // ── Phase 2: numeric for ─────────────────────────────────────────────────

    #[test]
